// Biomechanics and kinesiology topics for the Dr. MGR BPT Biomechanics, Applied Anatomy and Kinesiology paper (mechanics, joint and muscle structure and function, vertebral column). Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"bm-planes-motion", title:"Types of motion, planes, axes and direction of motion", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["planes and axes","types of motion","osteokinematics","arthrokinematics","degrees of freedom","roll slide spin","convex concave rule"],
  simple:"Movement of a body part is described by its type (straight-line or turning), the plane it moves in and the axis it turns around. Bones swing through space (osteokinematics) while the joint surfaces roll, slide and spin on each other (arthrokinematics). These words let everyone describe movement the same way.",
  flow:["Start from anatomical position as the reference","Name the motion type: translatory, rotatory or general","Name the plane: sagittal, frontal or transverse","Name the axis perpendicular to that plane","Describe the bone motion and its degrees of freedom","Describe surface motion: roll, slide, spin by convex-concave rule"],
  exam:[
    {h:"Introduction", p:["Kinematics describes motion without regard to the forces causing it: type, location, direction and magnitude of motion.","All human motion is described from the anatomical position: standing erect, face forward, arms by the side, palms forward."]},
    {h:"Types of motion", p:["Translatory (linear) motion: every point of the segment moves the same distance in the same direction; rectilinear (straight line) or curvilinear (curved path, e.g. a thrown ball).","Rotatory (angular) motion: the segment turns about a fixed axis, every point moving through the same angle; almost all joint motion is rotatory.","General (combined) motion: rotation plus translation, e.g. the whole body walking forward while limbs rotate at joints.","Magnitude is expressed in degrees for rotation and in centimetres for translation."]},
    {h:"Planes and axes", p:["Sagittal plane divides body into right and left; motion about a medio-lateral (frontal) axis: flexion and extension, dorsiflexion and plantarflexion.","Frontal (coronal) plane divides front and back; motion about an antero-posterior axis: abduction, adduction, lateral flexion, radial and ulnar deviation.","Transverse (horizontal) plane divides upper and lower; motion about a vertical (longitudinal) axis: medial and lateral rotation, pronation, supination, trunk rotation.","The axis is always perpendicular to the plane of motion. Cardinal planes pass through the centre of gravity; many functional movements occur in oblique planes."]},
    {h:"Direction terms and degrees of freedom", p:["Direction terms: anterior/posterior, superior/inferior, medial/lateral, proximal/distal, superficial/deep.","Degrees of freedom: number of independent planes a joint moves in. Uniaxial joints have 1 (elbow), biaxial 2 (wrist), triaxial 3 (hip, shoulder).","A free segment can have up to 6 degrees of freedom: 3 rotations and 3 translations."]},
    {h:"Osteokinematics and arthrokinematics", p:["Osteokinematics: movement of the bone shaft in space, e.g. shoulder flexion of 180 degrees.","Arthrokinematics: movement between joint surfaces: roll (new points meet new points), slide or glide (one point slides over many), spin (one point rotates on another, e.g. radial head in pronation).","Convex-concave rule: a convex surface moving on a fixed concave surface slides in the direction opposite to the bone movement (glenohumeral abduction, head slides inferiorly); a concave surface moving on a fixed convex surface slides in the same direction (tibia on femur in knee extension).","This rule guides the direction of joint mobilisation glides in physiotherapy."]},
    {h:"Clinical relevance and conclusion", p:["Goniometry, exercise description and documentation use these planes and axes.","Loss of normal accessory glide (e.g. inferior glide of the humeral head) blocks the main movement even when muscles are strong.","Correct description of type, plane, axis and arthrokinematics is the foundation of all later biomechanics."]}
  ],
  tip:"Draw a standing figure with three intersecting planes labelled sagittal, frontal and transverse, an arrow for each axis, and a small inset of a convex head on a concave socket showing roll and slide in opposite directions.",
  evidence:[["Mobilisation in the direction given by the convex-concave rule","Posterior glide restored shoulder ER better than anterior glide in one small trial, showing the rule is not always right","Low"],["Goniometry using standard planes and axes","Good reliability when the same tester uses a standard protocol","Moderate"]],
  evidenceSource:"Neumann 2017; Levangie and Norkin 2019; Johnson et al. 2007 (JOSPT)",
  outcomes:[["Goniometry","Osteokinematic range in each plane"],["Accessory glide grading (Kaltenborn or Maitland)","Arthrokinematic mobility"]],
  recent:["Wearable inertial measurement units (IMUs) and smartphone apps now let clinicians record joint angles in each plane outside the laboratory."],
  mnemonic:{word:"SaFT", items:[["Sa","Sagittal plane, medio-lateral axis: flexion and extension"],["F","Frontal plane, antero-posterior axis: abduction and adduction"],["T","Transverse plane, vertical axis: rotations"]], extra:"The axis is always at right angles to the plane."},
  example:"A 45-year-old teacher in Madurai has a stiff shoulder. She can flex only to 100 degrees. The physiotherapist notes the humeral head does not glide inferiorly and chooses inferior and posterior glides, using arthrokinematic reasoning rather than only stretching the bone into flexion.",
  flags:["Do not confuse plane with axis: they are always perpendicular","The convex-concave rule is a guide, not a law; re-assess after mobilisation","Excess accessory glide may mean instability, not stiffness"],
  viva:[["About which axis does shoulder abduction occur?","An antero-posterior (sagittal) axis, in the frontal plane."],["Give an example of spin.","Radial head spinning on the capitulum during pronation and supination."],["How many degrees of freedom does the hip have?","Three (triaxial)."]],
  refs:[{b:"levangie",ch:"Biomechanical applications to joint structure and function: kinematics"},{b:"neumann",ch:"Getting started: kinematics, osteokinematics and arthrokinematics"},{b:"brunnstrom",ch:"Mechanical principles: kinematics"}],
  keywords:"planes axes types of motion translatory rotatory osteokinematics arthrokinematics roll slide spin",
  mcq:[["Medial and lateral rotation of the hip occur in which plane?",["Sagittal","Frontal","Transverse","Oblique"],2,"Rotations occur in the transverse plane about a vertical axis."],["When a concave surface moves on a fixed convex surface, the slide is:",["Opposite to the bone movement","In the same direction as the bone movement","Absent","Always a spin"],1,"Concave on convex: roll and slide occur in the same direction."]]
},
{
  id:"bm-forces-newton", title:"Forces, vectors, force components and Newton's laws of motion", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["force vector","Newton laws","resolution of forces","rotary and translatory component","kinetics","joint reaction force"],
  simple:"A force is a push or pull that can change how a body moves. Because it has size and direction, it is drawn as an arrow called a vector. Newton's three laws explain how forces from muscles, gravity and the ground make our bodies move or stay still.",
  flow:["Identify every force: gravity, muscle, external, ground, joint reaction","Draw each as a vector with point, direction, magnitude","Resolve each force into perpendicular and parallel components","Perpendicular part rotates; parallel part compresses or distracts","Apply Newton's laws to predict motion or equilibrium","Use this to plan resistance, positioning and joint protection"],
  exam:[
    {h:"Definition of force", p:["Force is a push or pull that produces, stops or changes motion of a body; unit is newton (N). 1 N accelerates 1 kg at 1 m/s2.","Kinetics is the study of forces causing motion; kinematics only describes motion."]},
    {h:"Vectors and their characteristics", p:["A vector quantity has magnitude and direction (force, velocity, acceleration); a scalar has only magnitude (mass, speed).","A force vector is described by point of application, line of action, direction (arrow head) and magnitude (length of arrow).","Weight is the gravitational force on mass: W = m x g, acting vertically downward from the centre of mass.","Forces acting on the body: gravity, muscle (pull from insertion towards origin), external loads (weights, therapist hand, pulleys), ground reaction force, friction and joint reaction force."]},
    {h:"Composition and resolution of forces", p:["Composition: two or more forces combined into one resultant, by adding forces on the same line or by the parallelogram (or polygon) method for angled forces.","Resolution: one force split into two perpendicular components.","Perpendicular (rotary, y) component: produces rotation (torque) at the joint.","Parallel (translatory, x) component: along the bone; compressive (stabilising) if directed towards the joint, distractive if directed away.","When a muscle pulls at 90 degrees to the bone, all its force is rotary; at small angles most force compresses the joint."]},
    {h:"Newton's laws applied to the body", p:["First law (inertia): a body remains at rest or in uniform motion unless an unbalanced force acts. Static equilibrium means the sum of forces is zero.","Second law (acceleration): F = m x a; a larger force or smaller mass gives greater acceleration. Basis of impulse and of graded resistance.","Third law (action-reaction): for every action there is an equal and opposite reaction; ground reaction force in standing and gait, and joint reaction force between bone ends."]},
    {h:"Clinical relevance", p:["Placing a cuff weight further from the joint or at 90 degrees increases rotary demand; changing limb angle changes resistance through range.","Joint reaction forces can be several times body weight in activities like stair climbing, important in arthritis and after joint replacement.","Ground reaction force understanding guides gait analysis and footwear advice."]},
    {h:"Conclusion", p:["Every movement analysis starts by drawing forces as vectors, resolving them and applying Newton's laws."]}
  ],
  tip:"Draw the forearm at about 60 degrees with the biceps arrow from radial tuberosity, then dotted perpendicular (rotary) and parallel (compressive) components forming a right-angled triangle.",
  evidence:[["Hip joint contact forces measured with instrumented implants","Forces rise to a few times body weight in walking and more in stair climbing","High (direct measurement)"],["Use of free-body diagrams in teaching","Standard textbook method; not a clinical intervention","Expert consensus"]],
  evidenceSource:"Bergmann et al. 2001 (J Biomech) instrumented hip implants; Neumann 2017",
  outcomes:[["Force plate","Ground reaction force magnitude and direction"],["Handheld dynamometer","Muscle force output in newtons or kilograms"]],
  recent:["Instrumented joint implants (the OrthoLoad project) have provided in-vivo joint force data that confirm textbook estimates of high joint reaction forces."],
  mnemonic:{word:"I-A-R", items:[["I","Inertia: no change without a net force"],["A","Acceleration: F = m x a"],["R","Reaction: equal and opposite"]], extra:"Vector = point + line + direction + magnitude."},
  example:"A 70-year-old man in Chennai after total hip replacement is taught to carry his shopping bag in the hand on the operated side. This reduces the abductor force needed and therefore the hip joint reaction force, a direct use of force analysis.",
  flags:["Large compressive joint forces in painful arthritic or fresh fracture joints","Ignoring the parallel distractive component may stress healing ligaments","Sudden accelerations (Newton's second law) produce high forces in osteoporotic bone"],
  viva:[["What are the two components of a muscle force?","Perpendicular (rotary) and parallel (translatory: compressive or distractive)."],["State Newton's third law with a clinical example.","Action and reaction are equal and opposite, e.g. ground reaction force when standing."],["Unit of force?","Newton (kg m/s2)."]],
  refs:[{b:"levangie",ch:"Biomechanical applications: kinetics, force vectors and Newton's laws"},{b:"neumann",ch:"Biomechanical principles"},{b:"brunnstrom",ch:"Mechanical principles: kinetics"}],
  keywords:"force vector scalar resultant composition resolution Newton laws inertia acceleration reaction kinetics",
  mcq:[["The component of muscle force that produces joint rotation is the:",["Parallel component","Compressive component","Perpendicular component","Distractive component"],2,"The force perpendicular to the lever arm produces torque."],["Ground reaction force in standing illustrates Newton's:",["First law","Second law","Third law","Law of gravitation only"],2,"The ground pushes back equally and oppositely on the feet."]]
},
{
  id:"bm-centre-of-gravity", title:"Centre of gravity, line of gravity, base of support and stability", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["centre of gravity","COG","centre of mass","line of gravity","base of support","stability","balance"],
  simple:"The centre of gravity is the point where the whole body's weight can be thought to act. A vertical line drawn down from it is the line of gravity. You stay stable as long as this line falls inside the area under your feet or support.",
  flow:["Locate the centre of gravity of the body or segment","Drop the line of gravity vertically from it","Mark the base of support around all contact points","Stable if the line falls within the base","Stability improves with lower COG, wider base, more mass","Use this to plan positions, walking aids and fall prevention"],
  exam:[
    {h:"Definitions", p:["Centre of gravity (COG): the point at which the entire weight of a body may be considered to be concentrated; the point around which the body is balanced in all directions.","Centre of mass is the same point when gravity is uniform.","Line of gravity (LOG): the vertical line passing through the COG towards the earth.","Base of support (BOS): the area bounded by all points of contact with the supporting surface, including the area between the feet or between feet and walking aids."]},
    {h:"Location of COG in the human body", p:["In the adult standing in anatomical position the COG lies roughly anterior to the second sacral vertebra, about 55 percent of height from the floor (slightly lower in women).","It is relatively higher in infants (large head) and shifts with body build, pregnancy and limb position.","COG can lie outside the body, e.g. in forward bending; raising the arms raises the COG.","Each segment has its own COG; segment COGs are combined to find the whole-body COG."]},
    {h:"Line of gravity in ideal posture", p:["In the sagittal plane the LOG passes near the external auditory meatus, through the cervical and lumbar vertebral bodies, slightly behind the hip joint axis, slightly in front of the knee joint axis and in front of the lateral malleolus.","Gravity therefore produces small extension moments at hip and knee and a dorsiflexion moment at the ankle, resisted by ligaments and by calf muscle activity, giving energy-efficient standing."]},
    {h:"Stability and its factors", p:["Stable equilibrium: a slight displacement raises the COG and it returns (a cone on its base). Unstable: a slight displacement lowers the COG and it falls (cone on its tip). Neutral: COG stays at same height (a rolling ball).","Stability increases with: a lower COG, a larger BOS, LOG nearer the centre of the BOS, greater body mass, greater friction with the surface.","Widening the base in the direction of the expected force (stride stance when pushing) increases stability."]},
    {h:"Clinical relevance for physiotherapy", p:["Walking aids enlarge the BOS: walker gives the largest, then crutches, then a cane.","Elderly and neurological patients with poor balance are taught a wider stance and safe transfers.","Amputation, pregnancy and obesity shift the COG and require postural adaptation.","Patient positioning for treatment and the therapist's own body mechanics (walk-standing, bent knees) use these principles."]},
    {h:"Conclusion", p:["Balance depends on keeping the line of gravity within the base of support; physiotherapists change COG, BOS and muscle control to make patients safer."]}
  ],
  tip:"Draw a side view of a standing figure with a dot anterior to S2 and a vertical dashed line passing behind the hip, in front of the knee and in front of the ankle; add a footprint outline shaded as the base of support.",
  evidence:[["Multicomponent exercise including balance training for older adults","Reduces the rate of falls","High"],["Wider base of support with walking aids","Improves stability in people with balance loss","Expert consensus"]],
  evidenceSource:"Sherrington et al. 2019 Cochrane review of exercise for preventing falls; Levangie and Norkin 2019",
  outcomes:[["Berg Balance Scale","Static and dynamic balance and fall risk"],["Functional reach test","Limits of stability (how far the COG can move forward)"],["Timed Up and Go","Mobility and fall risk"]],
  recent:["The 2019 Cochrane review (Sherrington et al.) confirmed that exercise programmes, mainly balance and functional training, reduce falls in older people living in the community."],
  mnemonic:{word:"LOW-WIDE-HEAVY", items:[["LOW","Lower COG = more stable"],["WIDE","Wider BOS = more stable"],["HEAVY","Greater mass and friction = more stable"]], extra:"And keep the LOG near the middle of the BOS."},
  example:"A 78-year-old woman in Tiruchirappalli who has fallen twice is given a walker and taught to stand with feet a little apart while cooking. Both widen her base of support so her line of gravity stays inside it.",
  flags:["Recurrent falls need a full medical and fall-risk assessment","Sudden loss of balance may signal stroke or cerebellar disease","Patients with sensory loss in the feet rely more on vision; do not test balance eyes-closed without guarding"],
  viva:[["Where is the COG in an adult standing?","Roughly anterior to S2, about 55 percent of height."],["Name three factors that increase stability.","Low COG, wide BOS, LOG near the centre of the BOS (also mass, friction)."],["Which walking aid gives the largest base of support?","A walking frame (walker)."]],
  refs:[{b:"levangie",ch:"Biomechanical applications: centre of gravity and stability"},{b:"brunnstrom",ch:"Mechanical principles: gravity, stability and balance"},{c:"Sherrington C, Fairhall NJ, Wallbank GK, et al. Exercise for preventing falls in older people living in the community. Cochrane Database Syst Rev. 2019;(1):CD012424.", q:"Sherrington exercise for preventing falls older people community Cochrane 2019"}],
  keywords:"centre of gravity line of gravity base of support stability equilibrium balance",
  mcq:[["In ideal standing posture the line of gravity passes:",["Behind the knee joint axis","In front of the knee joint axis","Through the centre of the patella only","Behind the ankle joint"],1,"It passes slightly anterior to the knee, giving an extension moment resisted by the posterior capsule."],["Which change makes a patient LESS stable?",["Widening the stance","Lowering the centre of gravity","Raising both arms overhead","Using a walker"],2,"Raising the arms raises the COG and reduces stability."]]
},
{
  id:"bm-equilibrium-friction", title:"Equilibrium, friction, joint distraction and compression", subject:"Kinesiology", region:"Joints", stages:"steps",
  aliases:["static equilibrium","dynamic equilibrium","friction","coefficient of friction","joint distraction","joint compression","traction"],
  simple:"A body is in equilibrium when all forces and turning effects on it cancel out, so it does not speed up or slow down. Friction is the force that resists sliding between two surfaces. Joint distraction pulls the bone ends apart, while compression pushes them together.",
  flow:["List all forces and torques on the segment","Equilibrium: sum of forces and sum of torques equal zero","Friction equals coefficient times the normal force","Distraction forces pull joint surfaces apart","Capsule, ligaments and muscles resist distraction","Apply to traction, mobilisation, transfers and friction in gait"],
  exam:[
    {h:"Equilibrium", p:["A body is in equilibrium when the net force and the net torque acting on it are zero, so it has no linear or angular acceleration (Newton's first law).","Static equilibrium: the body is at rest, e.g. holding a limb still against gravity.","Dynamic equilibrium: the body moves at constant velocity.","Conditions: sum of vertical forces = 0, sum of horizontal forces = 0, sum of torques about any axis = 0. These equations are used to calculate unknown muscle and joint reaction forces."]},
    {h:"Friction", p:["Friction is a force that opposes the sliding of one surface on another, acting parallel to the surfaces.","Magnitude: friction = coefficient of friction (mu) x normal (compressive) force.","Static friction (before movement starts) is greater than kinetic friction (during sliding), so it takes more effort to start a movement than to continue it.","Friction depends on the nature of surfaces and the normal force, not on the contact area."]},
    {h:"Friction in the body and clinic", p:["Articular cartilage lubricated by synovial fluid has an extremely low coefficient of friction, lower than most engineered bearings; loss of cartilage in OA increases friction and wear.","Adequate floor friction is needed in gait; wet floors and smooth soles cause slips. Crutch and cane rubber tips increase friction.","Powder boards and sliding sheets reduce friction for assisted exercise or patient transfers.","Friction from skin shear contributes to pressure ulcers in bedridden patients."]},
    {h:"Joint distraction", p:["Distraction is a force pulling the joint surfaces apart, perpendicular to the joint surface; the parallel component of a force directed away from the joint is distractive.","Examples: weight of the hanging arm on the glenohumeral joint, a heavy bag carried in the hand, and manual or mechanical traction.","Distraction is resisted mainly by tension in the capsule and ligaments and by muscle contraction (e.g. supraspinatus and deltoid holding the humeral head).","Therapeutic distraction (Kaltenborn grades I-III) relieves pain, separates surfaces and stretches the capsule."]},
    {h:"Joint compression", p:["Compression pushes surfaces together; produced by body weight and by the compressive component of muscle forces.","Moderate intermittent compression nourishes cartilage by moving synovial fluid; excessive or constant compression damages cartilage.","Approximation is used in neurological rehabilitation to stimulate stabilising muscles."]},
    {h:"Conclusion", p:["Understanding equilibrium lets us calculate forces; managing friction, distraction and compression is central to traction, mobilisation, gait safety and joint protection."]}
  ],
  tip:"Draw the forearm held horizontally with three arrows (weight of forearm down, biceps up, joint reaction force down) and write the two equilibrium equations beside it; add a small diagram of joint surfaces being pulled apart labelled distraction.",
  evidence:[["Mechanical traction for low back pain","Little or no benefit over sham or other treatment","Moderate"],["Kaltenborn distraction with mobilisation for stiff joints","Short-term range gains in small trials","Low"]],
  evidenceSource:"Wegner et al. 2013 Cochrane review on traction for low back pain; Levangie and Norkin 2019",
  outcomes:[["Goniometry","Range after distraction mobilisation"],["NPRS","Pain relief after traction"]],
  recent:["Research on cartilage lubrication (boundary lubrication by lubricin and hyaluronic acid) explains the very low friction of healthy joints."],
  mnemonic:{word:"ZERO", items:[["Z","Zero net force"],["E","Equal and opposite torques"],["R","Rest or constant velocity"],["O","Only then equilibrium"]], extra:"Friction = mu x normal force; static friction > kinetic friction."},
  example:"A 35-year-old software engineer in Bengaluru with a stiff shoulder after immobilisation receives grade III inferior distraction-glides of the glenohumeral joint while the scapula is stabilised, followed by active exercise.",
  flags:["Distraction is contraindicated in joint instability, hypermobility and recent fracture","Rheumatoid cervical spine: risk of atlanto-axial instability with traction","Low friction floors and worn crutch tips cause falls"],
  viva:[["What are the conditions for static equilibrium?","Sum of forces is zero and sum of torques is zero."],["Is static friction greater or less than kinetic?","Greater."],["What resists distraction of the glenohumeral joint in standing?","Superior capsule, coracohumeral ligament and the supraspinatus and deltoid."]],
  refs:[{b:"levangie",ch:"Biomechanical applications: equilibrium, friction and joint distraction"},{b:"neumann",ch:"Biomechanical principles: static equilibrium"},{c:"Wegner I, Widyahening IS, van Tulder MW, et al. Traction for low-back pain with or without sciatica. Cochrane Database Syst Rev. 2013;(8):CD003010.", q:"Wegner traction for low-back pain Cochrane 2013"}],
  keywords:"equilibrium static dynamic friction coefficient joint distraction compression traction",
  mcq:[["Friction between two surfaces depends mainly on:",["Contact area","Coefficient of friction and normal force","Speed of movement only","Temperature only"],1,"F = mu x N; area does not matter in simple friction."],["Weight of a hanging arm on the glenohumeral joint produces:",["Compression","Distraction","Pure spin","Shear only"],1,"Gravity pulls the humerus away from the glenoid."]]
},
{
  id:"bm-concurrent-forces-pulleys", title:"Force systems: linear, concurrent, parallel, force couple; muscle action lines and anatomical pulleys", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["concurrent force system","force couple","line of pull","action line of muscle","anatomical pulley","patella as pulley","resultant force"],
  simple:"Several forces often act together on a bone. When their lines meet at one point they form a concurrent system, and they can be replaced by one resultant force. A muscle's line of pull decides what it does, and bony pulleys like the patella redirect or improve that pull.",
  flow:["Identify all forces acting on the segment","Classify the system: linear, concurrent, parallel or couple","Find the resultant by parallelogram or addition","Trace each muscle's action line relative to the joint axis","Note pulleys that redirect force or enlarge the moment arm","Apply to muscle testing, strengthening and surgical reasoning"],
  exam:[
    {h:"Force systems", p:["Linear force system: forces act along the same line (e.g. two people pulling a rope, traction with body weight). Resultant = algebraic sum.","Concurrent force system: two or more forces act on the same point or their lines of action meet at one point, at an angle to each other. Resultant found by the parallelogram or polygon method.","Parallel force system: forces are parallel and act at different points; basis of levers.","Force couple: two equal, parallel and opposite forces acting at different points, producing pure rotation, e.g. upper trapezius, lower trapezius and serratus anterior rotating the scapula upward."]},
    {h:"Concurrent forces in muscles", p:["Muscles with broad attachments act as several concurrent forces: the anterior, middle and posterior deltoid combine to give a resultant that abducts the arm.","Two heads of gastrocnemius, two parts of pectoralis major and the two heads of a bipennate muscle each have a resultant.","The resultant of the quadriceps and patellar tendon pull is the compressive force on the patellofemoral joint."]},
    {h:"Muscle action line", p:["The action line is the line of the muscle's resultant pull, from insertion towards origin.","Its position relative to the joint axis decides the action: anterior to the axis of the elbow = flexion; posterior = extension; medial or lateral to the axis = adduction or abduction.","A muscle can change or reverse action with joint position (e.g. the adductor longus helps hip flexion from extension but extension from flexion; the clavicular part of pectoralis major flexes the shoulder).","The perpendicular distance from the action line to the axis is the moment arm, which decides torque."]},
    {h:"Anatomical pulleys", p:["A pulley changes the direction of a force and, in the body, can increase the moment arm of a muscle.","Patella: holds the quadriceps tendon away from the knee axis, increasing the moment arm and knee extension torque; patellectomy reduces quadriceps efficiency.","Lateral malleolus redirects peroneus longus and brevis; medial malleolus redirects tibialis posterior.","Trochlea of the orbit redirects the superior oblique; sesamoid bones of the hallux and the pulley system of the finger flexor sheaths (A2 and A4 annular pulleys) keep tendons close to bone and prevent bowstringing."]},
    {h:"Clinical relevance", p:["Exercise direction should follow the action line of the target muscle, e.g. diagonal PNF patterns.","Loss of a pulley (patellectomy, ruptured finger pulley in climbers) reduces force efficiency or causes bowstringing.","Force couple imbalance (weak serratus anterior) causes scapular dyskinesis."]},
    {h:"Conclusion", p:["Analysing force systems, action lines and pulleys explains why muscles act as they do and how injury or surgery changes their efficiency."]}
  ],
  tip:"Draw the three deltoid parts as three arrows meeting at the deltoid tuberosity with a thick resultant arrow, and a separate knee diagram showing the patella pushing the quadriceps tendon forward to lengthen the moment arm.",
  evidence:[["Biomechanical studies of patellectomy","Loss of patella reduces quadriceps moment arm and extension strength","Moderate"],["Serratus anterior and lower trapezius training for scapular dyskinesis","Improves scapular control and symptoms in some trials","Low-moderate"]],
  evidenceSource:"Neumann 2017; Levangie and Norkin 2019",
  outcomes:[["Manual muscle testing","Strength of muscle along its line of pull"],["Scapular dyskinesis test","Function of the scapular force couple"]],
  recent:["Musculoskeletal modelling tools such as OpenSim now estimate muscle moment arms and lines of action for each joint position from imaging."],
  mnemonic:{word:"LCPC", items:[["L","Linear: same line"],["C","Concurrent: meet at a point"],["P","Parallel: levers"],["C","Couple: equal, opposite, parallel, pure rotation"]], extra:"Pulleys change direction; the patella also increases the moment arm."},
  example:"A 20-year-old rock-climbing enthusiast in Pune feels a pop in his ring finger and later notices the flexor tendon lifting away from the bone on gripping. The A2 pulley has ruptured, so the tendon bowstrings and loses efficiency.",
  flags:["Visible bowstringing of a finger flexor tendon needs hand surgery referral","After patellectomy expect extensor lag and weakness","Do not assume a muscle's textbook action in every joint position"],
  viva:[["Define a force couple and give an example.","Two equal, opposite, parallel forces causing rotation; scapular upward rotation by trapezius and serratus anterior."],["What is the function of the patella as a pulley?","It increases the moment arm of the quadriceps, increasing extension torque."],["What is a concurrent force system?","Forces whose lines of action meet at a common point."]],
  refs:[{b:"levangie",ch:"Biomechanical applications: force systems, concurrent forces and anatomical pulleys"},{b:"neumann",ch:"Muscle: line of force, moment arm and pulleys"},{b:"brunnstrom",ch:"Mechanical principles: composition of forces and pulleys"}],
  keywords:"linear concurrent parallel force couple resultant parallelogram action line pulley patella",
  mcq:[["Upward rotation of the scapula by trapezius and serratus anterior is an example of:",["A linear force system","A force couple","A second-class lever","A pulley"],1,"Opposite-direction forces at different points produce pure rotation."],["The main mechanical function of the patella is to:",["Reduce quadriceps moment arm","Increase quadriceps moment arm","Act as a first-class lever","Limit knee flexion"],1,"It holds the tendon further from the knee axis."]]
},
{
  id:"bm-levers-torque", title:"Levers, torque, moment arm and mechanical advantage", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["levers in human body","first class lever","second class lever","third class lever","torque","moment arm","mechanical advantage"],
  simple:"A lever is a rigid bar that turns around a fixed point. In the body, bones are the bars, joints are the fulcrums and muscles apply the effort. Torque is the turning effect of a force, and it depends on how far the force acts from the joint.",
  flow:["Identify axis, effort force and resistance force","Classify the lever by what lies in the middle","Torque equals force times perpendicular distance","Mechanical advantage equals effort arm over resistance arm","MA above 1 favours force; below 1 favours speed and range","Use moment arms to grade resistance and protect joints"],
  exam:[
    {h:"Definitions", p:["Lever: a rigid bar rotating about a fixed axis (fulcrum) under two forces, effort (E) and resistance (R).","Torque (moment of force): the rotating effect of a force = force x perpendicular distance from the line of force to the axis; unit Nm.","Moment arm (lever arm): the perpendicular distance from the axis to the line of action of the force. Effort arm for the muscle, resistance arm for the load.","Mechanical advantage (MA) = effort arm / resistance arm."]},
    {h:"Classes of lever", p:["First class (axis between effort and resistance; EAR): head nodding at the atlanto-occipital joint (neck extensors vs weight of face), triceps extending the elbow (olecranon behind axis), hip abductors in single-leg stance. MA can be more or less than 1; designed for balance.","Second class (resistance between axis and effort; ARE): rising onto the toes with the metatarsal heads as axis, body weight through the ankle and calf pull at the heel (classic textbook example). MA greater than 1; favours force.","Third class (effort between axis and resistance; AER): biceps and brachialis flexing the elbow, quadriceps extending the knee against a cuff weight at the ankle. MA less than 1; favours speed and range; the most common lever in the body."]},
    {h:"Torque and angle", p:["Muscle torque is greatest when its line of pull is perpendicular to the bone, as moment arm is largest (biceps near 90 degrees elbow flexion).","Gravity torque of a limb is greatest when the limb is horizontal and zero when vertical.","For balance: effort x effort arm = resistance x resistance arm (law of the lever)."]},
    {h:"Application in physiotherapy", p:["Resistance is increased by moving the weight or the therapist's hand distally (longer resistance arm) and decreased by moving it proximally.","Bent-knee sit-ups and bent-arm abduction shorten the resistance arm for weak patients.","Joint protection in arthritis: carry loads close to the body; use a cane in the opposite hand to reduce hip abductor demand.","Lifting with load close to the spine reduces the extensor torque and disc compression."]},
    {h:"Wheel and axle and pulleys", p:["Wheel and axle (e.g. rotation of the humerus or vertebral column with muscles acting at the periphery) is a lever variant; pulleys change direction of force (see force systems)."]},
    {h:"Conclusion", p:["Most body levers are third class and trade force for speed and range, so muscles must generate large forces, producing high joint compressive forces that physiotherapists must respect."]}
  ],
  tip:"Draw three horizontal bars with a triangle fulcrum: first class with fulcrum in the middle (head nodding), second with load in the middle (toe raise) and third with effort in the middle (biceps); write EAR, ARE, AER under each.",
  evidence:[["Load-handling advice and training based on lever principles","Does not by itself prevent back pain at work","Moderate"],["Cane in the contralateral hand for hip OA","Reduces hip abductor demand and joint load in biomechanical studies","Low-moderate"]],
  evidenceSource:"Verbeek et al. 2011 Cochrane review on manual material handling advice; Neumann 2017",
  outcomes:[["Isokinetic or handheld dynamometer","Joint torque in Nm"],["Pain on loading tasks","Effect of moment arm changes on symptoms"]],
  recent:["Clinical guidelines now treat lifting technique advice alone as ineffective for back pain prevention, while still using lever principles to explain loading to patients."],
  mnemonic:{word:"FRE 123", items:[["1","Fulcrum in the middle"],["2","Resistance in the middle"],["3","Effort in the middle"]], extra:"Mechanical advantage = effort arm / resistance arm."},
  example:"A 62-year-old woman in Kochi with knee OA struggles with straight-leg raise using a 2 kg cuff at the ankle. The physiotherapist moves the weight to just above the knee, shortening the resistance arm so she can complete her sets.",
  flags:["Long lever exercises can overload weak or post-operative joints","Heavy distal loads raise joint compressive forces in arthritis","Do not apply long-lever resistance across a healing fracture"],
  viva:[["Which class of lever is most common in the body?","Third class."],["Define mechanical advantage.","Ratio of effort arm to resistance arm."],["At what elbow angle does the biceps produce maximum torque?","Around 90 degrees, where its moment arm is largest."]],
  refs:[{b:"levangie",ch:"Biomechanical applications: levers, torque and mechanical advantage"},{b:"brunnstrom",ch:"Mechanical principles: levers and torque"},{c:"Verbeek JH, Martimo KP, Karppinen J, et al. Manual material handling advice and assistive devices for preventing and treating back pain in workers. Cochrane Database Syst Rev. 2011;(6):CD005958.", q:"Verbeek manual material handling advice back pain Cochrane"}],
  keywords:"lever first second third class torque moment arm mechanical advantage effort resistance fulcrum",
  mcq:[["Elbow flexion by the biceps is an example of a:",["First-class lever","Second-class lever","Third-class lever","Pulley"],2,"Effort (biceps insertion) lies between axis (elbow) and resistance (hand)."],["Mechanical advantage is calculated as:",["Resistance arm / effort arm","Effort arm / resistance arm","Force x distance","Mass x acceleration"],1,"MA = effort arm divided by resistance arm."]]
},
{
  id:"bm-joint-tissues", title:"Joint design and joint tissues: fibrous tissue, cartilage and bone", subject:"Kinesiology", region:"Joints", stages:"steps",
  aliases:["joint tissues","connective tissue","collagen","articular cartilage","hyaline cartilage","fibrocartilage","Wolff's law","stress strain curve"],
  simple:"Joints are built from connective tissues: tough fibrous tissue (ligaments, tendons, capsule), smooth cartilage that covers bone ends, and strong bone underneath. Each tissue is designed for the forces it meets. They all adapt to loading, and weaken when loading stops.",
  flow:["Joint design balances mobility against stability","Fibrous tissue: collagen fibres resist tension","Cartilage: water-rich matrix resists compression, lowers friction","Bone: mineralised matrix resists compression and bending","All tissues are viscoelastic: creep and stress relaxation","Tissues adapt to load and weaken with immobilisation"],
  exam:[
    {h:"Joint design and basic components", p:["Joint design reflects function: stability-oriented joints (hip, sacroiliac) have congruent surfaces and strong ligaments; mobility-oriented joints (shoulder) sacrifice stability.","Connective tissue is made of cells (fibroblasts, chondrocytes, osteoblasts, osteocytes) and extracellular matrix: fibres (collagen, elastin) and ground substance (proteoglycans, glycosaminoglycans, water).","Collagen type I resists tension (ligament, tendon, bone); type II gives cartilage its framework; elastin allows stretch and recoil (ligamentum flavum)."]},
    {h:"Dense fibrous tissue", p:["Dense regular tissue: parallel collagen fibres for one-direction tension, e.g. tendons (muscle to bone) and many ligaments (bone to bone).","Dense irregular tissue: fibres in many directions to resist multi-directional stress, e.g. joint capsule, periosteum.","Poor blood supply means slow healing; ligaments contain mechanoreceptors that contribute to proprioception."]},
    {h:"Cartilage", p:["Hyaline (articular) cartilage: covers bone ends; type II collagen with proteoglycans that hold water; avascular and aneural, nourished by synovial fluid through loading and unloading; distributes load and gives near frictionless motion; very limited repair.","Fibrocartilage: dense type I collagen with some proteoglycan; menisci, intervertebral disc annulus, labrum, pubic symphysis; resists both compression and tension.","Elastic cartilage: ear and epiglottis; not important in joints."]},
    {h:"Bone", p:["Cortical (compact) bone resists bending and torsion; cancellous (trabecular) bone at the ends absorbs and transfers load, with trabeculae lined up along stress lines.","Bone is strongest in compression, weaker in tension and weakest in shear.","Wolff's law: bone remodels according to the loads placed upon it; loading increases density, disuse causes osteoporosis."]},
    {h:"Mechanical behaviour of tissues", p:["Stress-strain curve: toe region (crimp straightens), elastic (linear) region, plastic region (permanent deformation, microfailure) and failure point.","Viscoelasticity: response depends on rate and time of loading. Creep: continued deformation under a constant load (basis of prolonged stretch). Stress relaxation: decrease in stress at constant length.","Hysteresis: energy is lost as heat in each loading cycle."]},
    {h:"Clinical relevance and conclusion", p:["Low-load, prolonged stretch uses creep to lengthen tissue safely; rapid high loads are more likely to tear.","Immobilisation weakens ligaments and thins cartilage; graded loading restores them.","Knowledge of tissue design guides the timing and dosage of exercise after injury."]}
  ],
  tip:"Draw a stress-strain curve with labelled toe, elastic, plastic regions and failure point; beside it draw a synovial joint showing capsule, hyaline cartilage, synovial membrane and subchondral bone.",
  evidence:[["Progressive loading after ligament injury","Tissue strength recovers with graded load; disuse weakens it","Moderate (animal and human studies)"],["Prolonged low-load stretch for contracture","Small or no clinically important lasting change in contractures","Moderate"]],
  evidenceSource:"Harvey et al. 2017 Cochrane review on stretch for contractures; Levangie and Norkin 2019",
  outcomes:[["Goniometry","Range affected by capsular and ligament stiffness"],["Bone mineral density (DEXA)","Bone response to loading"]],
  recent:["MRI techniques such as T2 mapping now detect early cartilage matrix changes before visible thinning."],
  mnemonic:{word:"CCB", items:[["C","Collagen tissue: tension"],["C","Cartilage: compression and low friction"],["B","Bone: rigid support, Wolff's law"]], extra:"Viscoelastic tissues show creep, stress relaxation and hysteresis."},
  example:"A 22-year-old kabaddi player in Salem has a grade II knee MCL sprain. He is started on protected early movement and progressive loading, because healing ligament fibres line up and strengthen in response to controlled tension.",
  flags:["Loading into the plastic region causes permanent damage","Long immobilisation weakens ligament-bone junctions","Articular cartilage has very poor healing; avoid repeated impact on damaged joints"],
  viva:[["What type of collagen is found in articular cartilage?","Type II."],["State Wolff's law.","Bone adapts its structure to the loads placed on it."],["Define creep.","Continued deformation of a tissue under a constant load over time."]],
  refs:[{b:"levangie",ch:"Joint structure and function: joint tissues"},{b:"neumann",ch:"Basic structure and function of human joints"},{c:"Harvey LA, Katalinic OM, Herbert RD, et al. Stretch for the treatment and prevention of contractures. Cochrane Database Syst Rev. 2017;(1):CD007455.", q:"Harvey stretch for treatment and prevention of contractures Cochrane 2017"}],
  keywords:"joint tissues collagen elastin proteoglycan cartilage hyaline fibrocartilage bone Wolff law viscoelastic creep",
  mcq:[["Articular hyaline cartilage receives nutrition mainly from:",["Its own blood vessels","Synovial fluid through loading and unloading","Periosteum","Lymphatics"],1,"It is avascular; intermittent loading pumps fluid in and out."],["Continued deformation of a tissue under a constant load is called:",["Stress relaxation","Hysteresis","Creep","Elastic recoil"],2,"Creep is time-dependent elongation under constant load."]]
},
{
  id:"bm-joint-classification", title:"Classification of joints and subtypes of synovial joints", subject:"Kinesiology", region:"Joints", stages:"steps",
  aliases:["joint classification","synarthrosis","amphiarthrosis","diarthrosis","synovial joint types","close packed position","ovoid and sellar joints"],
  simple:"Joints are grouped by what joins the bones (fibrous, cartilage or a fluid-filled cavity) and by how much they move. Synovial joints are the freely movable ones and come in several shapes, such as hinge and ball-and-socket. The shape decides which movements are possible.",
  flow:["Classify by tissue: fibrous, cartilaginous, synovial","Or by movement: synarthrosis, amphiarthrosis, diarthrosis","Describe the parts of a synovial joint","Subclassify synovial joints by shape and axes","Note close-packed and loose-packed positions","Relate shape to mobility, stability and injury"],
  exam:[
    {h:"Introduction", p:["A joint (articulation) is the junction between two or more bones. Classification may be structural (the binding tissue) or functional (amount of movement)."]},
    {h:"Fibrous and cartilaginous joints", p:["Synarthroses (fibrous, little or no movement): sutures of the skull, gomphosis (tooth in socket), syndesmosis (distal tibiofibular joint, interosseous membrane).","Amphiarthroses (cartilaginous, slight movement): primary cartilaginous or synchondrosis (epiphyseal plate, first sternocostal joint) and secondary cartilaginous or symphysis (pubic symphysis, intervertebral disc joints, manubriosternal joint)."]},
    {h:"Synovial joints (diarthroses)", p:["Features: articular hyaline cartilage, joint cavity, fibrous capsule lined by synovial membrane, synovial fluid, ligaments; some have discs, menisci, labra and fat pads.","Synovial fluid lubricates and nourishes cartilage; capsule and ligaments provide stability; mechanoreceptors give proprioception."]},
    {h:"Subtypes of synovial joints", p:["Uniaxial: hinge (ginglymus): humeroulnar, interphalangeal, ankle (talocrural); pivot (trochoid): median atlanto-axial, proximal and distal radioulnar.","Biaxial: condyloid or ellipsoid: radiocarpal, metacarpophalangeal; saddle (sellar): first carpometacarpal of thumb.","Triaxial: ball and socket (spheroidal): glenohumeral, hip.","Plane (gliding, nonaxial): intercarpal, acromioclavicular, facet joints of the spine.","Levangie and Neumann also describe joints by surface shape: ovoid (one convex and one concave surface) and sellar (each surface both convex and concave)."]},
    {h:"Close-packed and loose-packed positions", p:["Close-packed: maximum congruence and capsule-ligament tension, joint most stable, accessory motion least. Examples: knee full extension with tibial lateral rotation, hip extension with medial rotation and abduction, glenohumeral abduction with lateral rotation, ankle full dorsiflexion, interphalangeal full extension, MCP (fingers) full flexion.","Loose-packed (resting) position: least congruence, capsule lax, maximum accessory motion; used for joint mobilisation and to reduce pain in effusion."]},
    {h:"Clinical relevance and conclusion", p:["Injuries such as fractures and dislocations often occur in close-packed positions under high force.","Mobilisation is started in the resting position; immobilisation of the MCP joints in flexion prevents collateral ligament shortening.","Joint shape and type explain normal range, degrees of freedom and patterns of disease."]}
  ],
  tip:"Draw a classification tree (fibrous, cartilaginous, synovial) and beside synovial draw six small shapes: hinge, pivot, condyloid, saddle, ball and socket and plane, each with an example.",
  evidence:[["Splinting hand in safe position (MCP flexion, IP extension)","Prevents collateral ligament shortening; widely recommended","Expert consensus"],["Mobilisation starting in the resting position","Recommended in manual therapy texts; limited trials","Low"]],
  evidenceSource:"Neumann 2017; Levangie and Norkin 2019",
  outcomes:[["Goniometry","Range in each degree of freedom"],["Accessory movement testing","Capsular laxity or stiffness"]],
  recent:["Dynamic ultrasound and MRI are increasingly used to see synovial joint structures and effusions in clinic."],
  mnemonic:{word:"He Pivots, Con Sad Ball Plane", items:[["He","Hinge: elbow, IP"],["Pivots","Pivot: atlanto-axial, radioulnar"],["Con","Condyloid: wrist, MCP"],["Sad","Saddle: thumb CMC"],["Ball","Ball and socket: hip, shoulder"],["Plane","Plane: intercarpal, facet"]], extra:"Close-packed = most stable, least accessory motion."},
  example:"A 28-year-old cook in Thanjavur sprains his finger. The physiotherapist splints the MCP joint in flexion and the IP joints in extension, the close-packed and safe positions, so the collateral ligaments do not shorten.",
  flags:["Joint injury in the close-packed position may mean fracture or dislocation","Rapid swelling after injury suggests haemarthrosis","Hot, red single joint: rule out septic arthritis"],
  viva:[["Name a saddle joint.","First carpometacarpal joint of the thumb."],["Close-packed position of the knee?","Full extension with lateral rotation of the tibia."],["Give an example of a syndesmosis.","Distal tibiofibular joint."]],
  refs:[{b:"levangie",ch:"Joint structure and function: joint design and classification"},{b:"neumann",ch:"Basic structure and function of human joints"},{c:"Chaurasia BD. Human Anatomy, Volume 1. Chapter: General anatomy - joints."}],
  keywords:"joint classification fibrous cartilaginous synovial hinge pivot condyloid saddle ball socket plane close packed",
  mcq:[["The radiocarpal joint is a:",["Hinge joint","Pivot joint","Condyloid (ellipsoid) joint","Saddle joint"],2,"It is biaxial, allowing flexion-extension and radial-ulnar deviation."],["The close-packed position of a joint is the position of:",["Maximum accessory motion","Maximum congruence and stability","Least ligament tension","Resting for mobilisation"],1,"Surfaces fit best and ligaments are taut."]]
},
{
  id:"bm-kinematic-chains", title:"Kinematic chains: open versus closed chain movement and exercise", subject:"Kinesiology", region:"Joints", stages:"steps",
  aliases:["open kinetic chain","closed kinetic chain","OKC","CKC","weight bearing exercise","kinematic chain"],
  simple:"A kinematic chain is a series of body segments linked by joints, like a leg made of thigh, shank and foot. If the end segment moves freely in space, it is an open chain; if the end is fixed, like the foot on the floor, it is a closed chain. Each type loads joints and muscles differently.",
  flow:["See limb as linked segments forming a chain","Open chain: distal segment free, moves alone","Closed chain: distal segment fixed, joints move together","Compare loading, muscle action and joint forces","Choose exercise type to suit the stage of healing","Combine both types in a full rehabilitation plan"],
  exam:[
    {h:"Definition", p:["A kinematic chain is a combination of several joints linking successive segments (Reuleaux, applied to the body by Steindler).","Open kinematic chain (OKC): the distal segment is free to move; one joint can move independently (e.g. knee extension in sitting, biceps curl, kicking a ball).","Closed kinematic chain (CKC): the distal segment is fixed or meets considerable resistance; movement at one joint causes predictable movement at others (e.g. squat, push-up, step-up, standing from a chair)."]},
    {h:"Features of open chain", p:["Usually non weight-bearing; isolated muscle and joint movement.","Distal segment moves on a fixed proximal segment.","Mostly concentric or eccentric work of one muscle group; often produces more shear and distraction at the joint.","Useful for isolating a weak muscle and for speed movements such as throwing."]},
    {h:"Features of closed chain", p:["Usually weight-bearing; multi-joint movement; proximal segment moves on a fixed distal segment.","Co-contraction of agonists and antagonists, joint compression and greater stability.","More functional and better for proprioception and balance training.","Example: in a squat the hip, knee and ankle flex together with quadriceps, hamstrings and gluteals all active."]},
    {h:"Clinical application", p:["After ACL reconstruction: OKC knee extension through the last 30-40 degrees increases anterior tibial translation and ACL strain early on, so it is often limited to 90-45 degrees initially; CKC squats are introduced early; both types are later combined.","Patellofemoral pain: OKC loads the patellofemoral joint more near extension, CKC more in deep flexion, so choose pain-free arcs.","Shoulder: CKC weight bearing on hands (wall push-up) for scapular stability; OKC for strength and throwing.","Neurological rehabilitation: CKC tasks such as sit-to-stand train functional control."]},
    {h:"Limitations of the concept", p:["Many activities are mixed (cycling, gait swing and stance), so the open-closed division is a spectrum.","Research shows both types can strengthen the quadriceps; choice depends on the goal and the healing tissue."]},
    {h:"Conclusion", p:["Understanding open and closed chains lets the physiotherapist choose safe, functional exercises at each stage of rehabilitation."]}
  ],
  tip:"Draw two stick legs: one sitting with foot free extending the knee (OKC) and one squatting with the foot fixed on the floor (CKC), with arrows showing which segment moves.",
  evidence:[["OKC versus CKC exercise after ACL injury or reconstruction","No clear difference in laxity, pain or function overall","Low-moderate"],["Exercise therapy for knee osteoarthritis","Reduces pain and improves function","High"]],
  evidenceSource:"Glass et al. 2010 systematic review (NAJSPT); Fransen et al. 2015 Cochrane review",
  outcomes:[["Single-leg hop tests","Functional knee performance"],["KOOS or Lysholm score","Knee function and symptoms"],["Isokinetic testing","Quadriceps and hamstring strength"]],
  recent:["Current ACL rehabilitation guidance supports including OKC quadriceps exercise in limited ranges early, alongside CKC work, rather than avoiding OKC altogether."],
  mnemonic:{word:"OFF and ON", items:[["OFF","Open: foot off the ground, free"],["ON","Closed: foot on the ground, fixed"]], extra:"Closed chain = co-contraction, compression, function."},
  example:"A 24-year-old footballer in Kolkata, 3 weeks after ACL reconstruction, does mini-squats and leg press (closed chain) and seated knee extension only from 90 to 45 degrees (open chain) to protect the graft while restoring quadriceps strength.",
  flags:["Avoid heavy OKC terminal knee extension early after ACL graft","Painful CKC loading in deep flexion in patellofemoral pain","Weight bearing CKC exercise is unsafe if weight bearing is restricted after fracture"],
  viva:[["Define a closed kinematic chain.","Distal segment fixed so movement at one joint produces movement at others."],["Give one OKC and one CKC exercise for the knee.","OKC: seated knee extension; CKC: squat."],["Why is CKC considered more functional?","It mimics weight-bearing tasks with co-contraction and joint compression."]],
  refs:[{b:"levangie",ch:"Joint structure and function: kinematic chains"},{b:"brunnstrom",ch:"Kinematic chains and their application"},{c:"Glass R, Waddington G, Cooper K, et al. The effects of open versus closed kinetic chain exercises on patients with ACL deficient or reconstructed knees: a systematic review. N Am J Sports Phys Ther. 2010;5(2):74-84.", q:"Glass open versus closed kinetic chain ACL systematic review 2010"}],
  keywords:"kinematic chain open closed OKC CKC weight bearing ACL exercise",
  mcq:[["Which is a closed kinematic chain exercise?",["Seated knee extension","Biceps curl","Push-up","Straight leg raise"],2,"Hands are fixed on the floor while the body moves."],["A feature of closed chain exercise is:",["Isolated single-joint movement","Distal segment moving freely","Co-contraction and joint compression","Non weight-bearing"],2,"CKC usually involves co-contraction and compression."]]
},
{
  id:"bm-joint-injury-disease", title:"Effects of injury, disease and immobilisation on joint structure and function", subject:"Kinesiology", region:"Joints", stages:"012334",
  aliases:["effects of immobilisation on joints","joint pathology","capsular pattern","joint stiffness","osteoarthritis biomechanics","rheumatoid arthritis effects on joints","hypomobility hypermobility"],
  simple:"When a joint is injured, diseased or kept still for long, its tissues change. Ligaments weaken, cartilage thins, the capsule stiffens and muscles waste, so the joint becomes stiff, painful or unstable. Early, safe movement and loading help to prevent and reverse these changes.",
  flow:["Cause: trauma, inflammation, degeneration or immobilisation","Tissue change: cartilage, capsule, ligament, bone, muscle","Signs: pain, effusion, stiffness or instability, deformity","Assess ROM, end feel, capsular pattern, stability tests","Treat with protected movement, mobilisation and strengthening","Prevent recurrence with load management and joint protection"],
  exam:[
    {h:"Introduction", p:["Joint function depends on healthy tissues and normal loading. Trauma, disease and disuse alter the structure of every joint tissue and therefore its mechanics."]},
    {h:"Effects of immobilisation and disuse", p:["Cartilage: thinning and softening, loss of proteoglycans, adhesion of synovium to cartilage.","Capsule and ligament: random collagen cross-links, adhesions, contracture; ligament strength and ligament-bone junction strength fall, with recovery taking much longer than the period of immobilisation.","Bone: loss of mineral density (disuse osteoporosis).","Muscle: atrophy (type I fibres early in antigravity muscles), shortening if kept in a shortened position, loss of strength and endurance."]},
    {h:"Effects of trauma", p:["Sprain (ligament): grade I microtear, grade II partial tear with some laxity, grade III complete tear with instability.","Dislocation and subluxation, fracture into the joint (intra-articular), meniscal and labral tears.","Effusion inhibits muscles (arthrogenic muscle inhibition, e.g. quadriceps after knee injury) and alters joint position sense.","Instability leads to repeated giving way and secondary degeneration."]},
    {h:"Effects of disease", p:["Osteoarthritis: cartilage fibrillation and loss, subchondral sclerosis, osteophytes, capsular thickening; joint space narrowing, crepitus, deformity (genu varum).","Rheumatoid arthritis: synovial inflammation and pannus eroding cartilage and bone, ligament laxity leading to deformities (ulnar drift, swan neck, boutonniere, atlanto-axial instability).","Ankylosing spondylitis: enthesitis and fusion of spinal joints.","Other: haemophilic arthropathy, gout, infection, neuropathic (Charcot) joints."]},
    {h:"Assessment and physiotherapy management", p:["Assess pain, swelling, active and passive range, end feel, capsular pattern (e.g. shoulder: lateral rotation most limited, then abduction, then medial rotation), accessory movements, stability tests and muscle strength.","Hypomobility: joint mobilisation (Maitland grades III-IV), stretching, active exercise, heat before stretching.","Hypermobility or instability: stabilisation, proprioceptive and strengthening exercise; avoid end-range stress.","Inflamed joints: rest in resting position, splints, gentle active or isometric exercise, cold, joint protection education."]},
    {h:"Prevention and conclusion", p:["Early controlled movement (continuous passive motion, active exercise) and progressive loading after injury limit the harmful effects of immobilisation.","Understanding these changes lets the physiotherapist explain stiffness and weakness and plan graded rehabilitation."]}
  ],
  tip:"Draw a normal and an osteoarthritic synovial joint side by side, labelling cartilage loss, osteophytes, subchondral sclerosis and narrowed joint space; add a box listing changes of immobilisation by tissue.",
  evidence:[["Land-based exercise for knee osteoarthritis","Reduces pain and improves function","High"],["Early mobilisation versus prolonged immobilisation after ankle sprain","Early functional treatment gives better outcomes","Moderate"],["Continuous passive motion after knee replacement","Little or no clinically important benefit","Moderate"]],
  evidenceSource:"Fransen et al. 2015 Cochrane review; Harvey et al. 2014 Cochrane review on CPM after TKR; Kerkhoffs et al. 2002 Cochrane review on ankle sprain",
  outcomes:[["Goniometry","Range of motion lost or regained"],["WOMAC or KOOS","Pain, stiffness and function in arthritis"],["Joint girth","Effusion"]],
  recent:["Programmes such as GLA:D (Good Life with osteoArthritis in Denmark) deliver structured education and exercise for hip and knee OA and have spread to many countries."],
  mnemonic:{word:"CLAMB", items:[["C","Cartilage thins"],["L","Ligaments weaken"],["A","Adhesions in capsule"],["M","Muscle atrophy"],["B","Bone loses density"]], extra:"Effects of immobilisation on a joint."},
  example:"A 40-year-old labourer in Vellore comes out of a 6-week above-knee cast with a stiff knee bent to only 60 degrees and a weak quadriceps. Patellar and tibiofemoral mobilisation, active exercise and graded weight bearing are started, and he is told that ligament strength will take months to return.",
  flags:["Hot, swollen, painful joint with fever: suspect septic arthritis","Gross instability after trauma needs imaging for fracture or complete rupture","Atlanto-axial instability in rheumatoid arthritis: avoid neck manipulation and end-range flexion"],
  viva:[["What is the capsular pattern of the shoulder?","Lateral rotation most limited, then abduction, then medial rotation."],["What happens to cartilage during immobilisation?","It thins, softens and loses proteoglycans."],["What is arthrogenic muscle inhibition?","Reflex inhibition of muscles around a swollen or injured joint, e.g. quadriceps after knee effusion."]],
  refs:[{b:"levangie",ch:"Joint structure and function: effects of disease, injury and immobilisation"},{b:"neumann",ch:"Basic structure and function of human joints: effects of immobilisation and ageing"},{c:"Fransen M, McConnell S, Harmer AR, et al. Exercise for osteoarthritis of the knee. Cochrane Database Syst Rev. 2015;(1):CD004376.", q:"Fransen exercise for osteoarthritis of the knee Cochrane 2015"}],
  keywords:"immobilisation effects joint injury disease osteoarthritis rheumatoid capsular pattern stiffness instability",
  mcq:[["After prolonged immobilisation, ligament strength:",["Is unchanged","Recovers faster than the period of immobilisation","Decreases and takes longer to recover than the immobilisation period","Increases"],2,"Ligament and insertion strength recover slowly after disuse."],["Ulnar drift of the fingers is typical of:",["Osteoarthritis","Rheumatoid arthritis","Gout","Ankylosing spondylitis"],1,"Synovitis and ligament laxity at the MCP joints cause ulnar drift."]]
},
{
  id:"bm-length-tension", title:"Length-tension relationship: active and passive tension", subject:"Kinesiology", region:"Muscle", stages:"steps",
  aliases:["length tension curve","active tension","passive tension","total tension","sarcomere overlap","force velocity relationship","titin"],
  simple:"A muscle can produce the most force at a middle length where its actin and myosin filaments overlap best. If it is too short or too stretched, it gets weaker. When stretched, the muscle's elastic parts also pull back, adding passive tension.",
  flow:["Muscle force depends on its length at contraction","Active tension: cross-bridges, best at optimal overlap","Too short: filaments overlap and collide; force falls","Too long: few cross-bridges; active force falls","Passive tension rises beyond resting length from elastic tissue","Total tension = active + passive; use in positioning and testing"],
  exam:[
    {h:"Definition", p:["The length-tension relationship describes how the force (tension) a muscle can develop varies with its length at the time of activation.","Total tension = active tension (from contractile cross-bridges) + passive tension (from stretched non-contractile tissue)."]},
    {h:"Active tension", p:["Produced by actin-myosin cross-bridge cycling within sarcomeres.","Maximum at an intermediate (around resting) length where overlap gives the most cross-bridges.","At short lengths the thin filaments overlap each other and myosin hits the Z-discs, so force falls.","At long lengths overlap reduces and fewer cross-bridges form, so force falls."]},
    {h:"Passive tension", p:["Develops when the muscle is stretched beyond its resting length, even without contraction.","Sources: the giant protein titin within the sarcomere and the connective tissue (endomysium, perimysium, epimysium) and tendon.","Acts like a stretched rubber band storing elastic energy (stretch-shortening cycle in jumping).","Excess passive tension limits range of motion (tight hamstrings)."]},
    {h:"Total tension curve", p:["At short and resting lengths total tension is mostly active.","At longer lengths, passive tension adds to the falling active tension, so total tension may stay high or rise.","Muscles with more connective tissue reach high passive tension earlier."]},
    {h:"Related relationship: force-velocity", p:["In concentric contraction, force decreases as shortening speed increases.","In eccentric contraction, force increases with lengthening speed up to a plateau and is higher than isometric force.","Isometric force lies between them."]},
    {h:"Clinical relevance and conclusion", p:["Manual muscle testing is done at a standard position because strength varies with length.","Weak muscles may be strengthened first in mid-range, where they are strongest.","Prolonged shortening (e.g. plaster in plantarflexion) reduces sarcomere number and shifts the curve; prolonged lengthening adds sarcomeres.","Pre-stretch before a jump uses passive and reflex tension to improve performance (plyometrics)."]}
  ],
  tip:"Plot a graph with muscle length on the x-axis and tension on the y-axis: a bell-shaped active curve, a passive curve rising beyond resting length, and a dashed total tension curve; mark small sarcomere diagrams at short, optimal and long lengths.",
  evidence:[["Eccentric training (Nordic hamstring) to prevent hamstring injury","Reduces hamstring strain injuries in athletes","Moderate"],["Plyometric training using stretch-shortening","Improves jump performance","Moderate"]],
  evidenceSource:"van der Horst et al. 2015 (Am J Sports Med); Neumann 2017",
  outcomes:[["Dynamometry at different joint angles","Torque-angle (length-tension) curve"],["Countermovement versus squat jump height","Use of the stretch-shortening cycle"]],
  recent:["Ultrasound imaging of muscle fascicles during movement now shows fascicle length changes directly in living people."],
  mnemonic:{word:"Middle is Mighty", items:[["Short","Filaments collide, weak"],["Middle","Best overlap, strongest"],["Long","Few cross-bridges, active weak, passive rises"]], extra:"Total = active + passive."},
  example:"A 55-year-old woman in Mysuru with weak quadriceps after knee surgery cannot extend fully against resistance. The physiotherapist trains her first in mid-range (about 60-30 degrees), where the muscle is strongest, and gradually progresses to full range.",
  flags:["Stretching a weak, overstretched muscle further reduces its active force","Prolonged immobilisation in a shortened position shifts the curve and causes contracture","Fast eccentric loads can strain muscles at long lengths"],
  viva:[["At what length does a muscle produce maximum active tension?","At about its resting (intermediate) length."],["Name the sources of passive tension.","Titin and the connective tissue sheaths and tendon."],["What happens to concentric force as speed increases?","It decreases (force-velocity relationship)."]],
  refs:[{b:"levangie",ch:"Muscle structure and function: length-tension relationship"},{b:"neumann",ch:"Muscle: the primary stabiliser and mover of the skeletal system"},{c:"Gordon AM, Huxley AF, Julian FJ. The variation in isometric tension with sarcomere length in vertebrate muscle fibres. J Physiol. 1966;184(1):170-192.", q:"Gordon Huxley Julian 1966 isometric tension sarcomere length"}],
  keywords:"length tension relationship active passive total tension sarcomere overlap titin force velocity",
  mcq:[["Passive tension in a muscle arises mainly from:",["Actin-myosin cross-bridges","Titin and connective tissue","Calcium release","Motor unit recruitment"],1,"Non-contractile elements resist stretch."],["Active tension is maximum when the muscle is:",["Fully shortened","At about resting length","Fully stretched","Paralysed"],1,"Optimal actin-myosin overlap gives the most cross-bridges."]]
},
{
  id:"bm-insufficiency", title:"Active and passive insufficiency of two-joint muscles", subject:"Kinesiology", region:"Muscle", stages:"steps",
  aliases:["active insufficiency","passive insufficiency","two joint muscle","multi joint muscle","tenodesis","hamstring tightness"],
  simple:"A muscle that crosses two joints cannot do full work at both joints at once. When it shortens over both joints it runs out of force (active insufficiency). When it is stretched over both joints it runs out of length and blocks movement (passive insufficiency).",
  flow:["Identify a muscle crossing two or more joints","Shorten it over all joints together","It cannot generate enough force: active insufficiency","Lengthen it over all joints together","It cannot stretch enough and stops motion: passive insufficiency","Use the concept in testing, stretching and tenodesis"],
  exam:[
    {h:"Definition", p:["Active insufficiency: a multi-joint muscle cannot shorten enough to produce full range at all its joints simultaneously, because it reaches a length where it develops little active tension (length-tension curve).","Passive insufficiency: a multi-joint muscle cannot lengthen enough to allow full range of the opposite movement at all its joints at the same time; its passive tension stops the movement."]},
    {h:"Examples of active insufficiency", p:["Hamstrings: knee flexion is weaker when the hip is extended (prone) because the muscle is already short at the hip.","Finger flexors: grip is weak with the wrist fully flexed; you cannot make a tight fist.","Rectus femoris: knee extension is weaker with the hip fully flexed.","Gastrocnemius: plantarflexion force falls when the knee is flexed, so soleus is tested with the knee bent."]},
    {h:"Examples of passive insufficiency", p:["Hamstrings limit hip flexion when the knee is extended (straight leg raise), but not when the knee is bent.","Rectus femoris limits knee flexion when the hip is extended (Ely's test).","Finger extensors stop full finger flexion when the wrist is fully flexed.","Gastrocnemius limits ankle dorsiflexion with the knee extended."]},
    {h:"Clinical applications", p:["Muscle testing: isolate one-joint muscles by placing the two-joint muscle in active insufficiency (soleus with knee flexed; hamstrings vs gluteus maximus).","Muscle length tests: SLR for hamstrings, Thomas and Ely's tests for rectus femoris, knee straight and bent dorsiflexion for gastrocnemius vs soleus.","Stretching a two-joint muscle requires lengthening across both joints.","Tenodesis action: in C6 tetraplegia, active wrist extension passively pulls the finger flexors tight to make a functional grip; finger flexors must not be over-stretched."]},
    {h:"Synergy in normal function", p:["Normal movement avoids insufficiency by combining movements, e.g. in walking, hip flexion with knee flexion keeps the hamstrings at a useful length.","Wrist extensors act as synergists during gripping to keep finger flexors at an efficient length."]},
    {h:"Conclusion", p:["Active and passive insufficiency are applications of the length-tension relationship to two-joint muscles and are essential for accurate testing and stretching."]}
  ],
  tip:"Draw the lower limb in two positions: hip extended with knee flexed (hamstrings short, active insufficiency) and SLR with knee straight (hamstrings stretched, passive insufficiency), labelling each with arrows.",
  evidence:[["Preserving tenodesis grip in tetraplegia by avoiding stretch of finger flexors","Recommended practice to keep functional grip","Expert consensus"],["Hamstring stretching programmes","Increase SLR range in the short term","Moderate"]],
  evidenceSource:"Levangie and Norkin 2019; Harvey et al. 2017 Cochrane review on stretch",
  outcomes:[["Straight leg raise angle","Hamstring passive insufficiency"],["Thomas and Ely's tests","Hip flexor and rectus femoris length"],["Grip dynamometer at different wrist positions","Active insufficiency of finger flexors"]],
  recent:["Shear-wave elastography lets researchers measure passive stiffness of two-joint muscles such as the hamstrings in different joint positions."],
  mnemonic:{word:"Short-Weak, Long-Stuck", items:[["Active","Too short at both joints: weak"],["Passive","Too long at both joints: movement stuck"]], extra:"Only multi-joint muscles show insufficiency."},
  example:"A 19-year-old with C6 tetraplegia after a diving accident in Goa learns to pick up a cup by extending his wrist; the tight finger flexors pull the fingers closed. The team avoids fully stretching his finger flexors so this tenodesis grip is preserved.",
  flags:["Over-stretching finger flexors in tetraplegia destroys tenodesis","Sciatic nerve tension can mimic hamstring tightness in SLR","Do not force stretch across both joints after hamstring tear"],
  viva:[["Why is grip weak with the wrist flexed?","Finger flexors are in active insufficiency; finger extensors add passive insufficiency."],["How do you test soleus separately from gastrocnemius?","Plantarflexion with the knee flexed, putting gastrocnemius in active insufficiency."],["What is tenodesis grip?","Finger flexion produced passively by wrist extension through tight finger flexors."]],
  refs:[{b:"levangie",ch:"Muscle structure and function: active and passive insufficiency"},{b:"brunnstrom",ch:"Muscle activity: multi-joint muscles and insufficiency"},{b:"neumann",ch:"Muscle: multi-articular muscles"}],
  keywords:"active insufficiency passive insufficiency two joint muscle hamstrings rectus femoris tenodesis",
  mcq:[["Inability to make a tight fist with the wrist fully flexed is mainly due to:",["Passive insufficiency of finger flexors","Active insufficiency of finger flexors","Weakness of the lumbricals","Active insufficiency of wrist extensors"],1,"Finger flexors are too short across both wrist and fingers."],["Limitation of hip flexion in SLR with the knee straight is due to:",["Active insufficiency of hamstrings","Passive insufficiency of hamstrings","Weak iliopsoas","Tight rectus femoris"],1,"Hamstrings cannot lengthen across both hip and knee."]]
},
{
  id:"bm-contraction-types", title:"Types of muscle contraction: concentric, eccentric, isometric and isokinetic", subject:"Kinesiology", region:"Muscle", stages:"steps",
  aliases:["isometric contraction","isotonic contraction","concentric","eccentric","isokinetic","static and dynamic work","DOMS"],
  simple:"Muscles can work without changing length (isometric), while shortening (concentric) or while lengthening under control (eccentric). Isokinetic work keeps the speed of movement constant, using a special machine. Each type has its own uses in exercise.",
  flow:["Isometric: tension without joint movement","Concentric: muscle shortens, torque beats the load","Eccentric: muscle lengthens, load beats muscle torque","Isokinetic: constant angular velocity with a dynamometer","Compare force, energy cost and soreness","Choose type to suit tissue healing and functional goal"],
  exam:[
    {h:"Introduction", p:["Muscle contraction (activation) is the generation of tension. It is classified by change of muscle length and by velocity.","Static (isometric) and dynamic (isotonic: concentric and eccentric; isokinetic) work."]},
    {h:"Isometric contraction", p:["Tension develops but the muscle length and joint angle do not change visibly; muscle torque equals resistance torque.","Examples: holding a glass still; quadriceps setting after knee surgery; postural holding.","Strength gain is mostly specific to the trained angle (about 10-20 degrees either side); can raise blood pressure, so avoid breath-holding (Valsalva).","Typical dose: 6-10 second holds, 10 repetitions, several times a day."]},
    {h:"Concentric and eccentric contraction", p:["Concentric: muscle shortens as it overcomes resistance; positive work; e.g. biceps lifting a cup, quadriceps rising from a chair.","Eccentric: muscle lengthens while controlling a load greater than its force; negative work; e.g. quadriceps lowering into a chair, biceps lowering a cup, tibialis anterior controlling foot lowering after heel strike.","Eccentric contractions produce more force, use less oxygen and fewer motor units for the same load, but cause more delayed onset muscle soreness (DOMS) at 24-72 hours.","Isotonic is a common term for both, though torque actually varies through range."]},
    {h:"Isokinetic contraction", p:["Movement at a constant angular velocity controlled by a dynamometer (e.g. Cybex, Biodex), which matches resistance to the force applied.","Allows maximal loading through the whole range; can be concentric or eccentric; speeds from slow (about 60 degrees per second, strength) to fast (180-300 degrees per second, endurance and function).","Used for testing (peak torque, hamstring-quadriceps ratio) and training; expensive and not functional."]},
    {h:"Physiotherapy applications", p:["Early after injury or surgery: isometrics to limit atrophy without moving the joint.","Strengthening: concentric and eccentric progressive resistance.","Eccentric loading for tendinopathy (Alfredson heel drop for Achilles: 3 sets of 15, twice daily, for 12 weeks) and Nordic hamstring exercise for injury prevention.","Functional training mixes all types, as in sit-to-stand and stairs."]},
    {h:"Conclusion", p:["Knowing contraction types lets the therapist choose safe early exercise and progress to functional, sport-specific loading."]}
  ],
  tip:"Draw a biceps curl in three panels: holding still (isometric), lifting (concentric, arrow showing shortening) and lowering (eccentric, arrow showing lengthening), and a small isokinetic dynamometer graph with flat velocity line.",
  evidence:[["Eccentric loading for Achilles tendinopathy","Reduces pain and improves function in many trials","Moderate"],["Nordic hamstring eccentric programme","Reduces hamstring injury rates","Moderate"],["Isometric exercise for resting blood pressure","Small reductions in resting blood pressure","Moderate"]],
  evidenceSource:"Alfredson et al. 1998 (Am J Sports Med); van der Horst et al. 2015 (Am J Sports Med); Neumann 2017",
  outcomes:[["Isokinetic peak torque","Strength at set velocities"],["VISA-A questionnaire","Achilles tendinopathy severity"],["1RM or 10RM","Dynamic strength"]],
  recent:["Heavy slow resistance (combined concentric and eccentric) has been shown to be as effective as eccentric-only loading for some tendinopathies."],
  mnemonic:{word:"I-C-E-I", items:[["I","Isometric: same length"],["C","Concentric: comes closer (shortens)"],["E","Eccentric: extends (lengthens)"],["I","Isokinetic: identical speed"]], extra:"Eccentric = most force, least energy, most soreness."},
  example:"A 38-year-old runner in Hyderabad with mid-portion Achilles tendinopathy performs slow eccentric heel drops on a step with the knee straight and bent, 3 sets of 15 twice daily for 12 weeks.",
  flags:["Isometric breath-holding raises BP: caution in hypertension and cardiac disease","Unaccustomed eccentric work causes DOMS; progress gradually","Avoid heavy eccentric loading on a fresh muscle tear"],
  viva:[["Which contraction produces the greatest force?","Eccentric."],["Give an example of eccentric work of the quadriceps.","Sitting down into a chair or walking downstairs."],["What does an isokinetic dynamometer control?","Angular velocity (speed) of movement."]],
  refs:[{b:"levangie",ch:"Muscle structure and function: types of contraction"},{b:"brunnstrom",ch:"Muscle activity and strength"},{c:"Alfredson H, Pietila T, Jonsson P, Lorentzon R. Heavy-load eccentric calf muscle training for the treatment of chronic Achilles tendinosis. Am J Sports Med. 1998;26(3):360-366.", q:"Alfredson heavy-load eccentric calf muscle training Achilles 1998"}],
  keywords:"isometric isotonic concentric eccentric isokinetic contraction DOMS dynamometer",
  mcq:[["Lowering into a chair uses the quadriceps:",["Concentrically","Eccentrically","Isometrically","Isokinetically"],1,"The muscle lengthens while controlling body weight."],["Which is TRUE of eccentric contraction?",["It uses more oxygen than concentric","It produces less force than isometric","It produces the greatest force","It never causes soreness"],2,"Eccentric work produces the highest force for the least energy."]]
},
{
  id:"bm-spurt-shunt-roles", title:"Spurt and shunt muscles, tonic and phasic muscles; agonist, antagonist and synergist", subject:"Kinesiology", region:"Muscle", stages:"steps",
  aliases:["spurt muscle","shunt muscle","tonic and phasic muscles","postural muscles","prime mover","antagonist","synergist","fixator stabiliser neutraliser"],
  simple:"Muscles can be grouped by how they attach (spurt muscles move the bone fast, shunt muscles hold the joint together), by their usual job (tonic muscles hold posture, phasic muscles make quick movements) and by their role in a movement (agonist, antagonist, synergist).",
  flow:["Spurt: origin far, insertion near joint, rotary force","Shunt: origin near, insertion far, compressive force","Tonic: postural, slow fibres, tend to tighten","Phasic: movement, fast fibres, tend to weaken","Agonist moves, antagonist opposes, synergist assists or stabilises","Apply to muscle imbalance and exercise selection"],
  exam:[
    {h:"Spurt and shunt muscles (MacConaill)", p:["Spurt muscle: origin far from the joint and insertion close to it; most of its force is rotary, so it accelerates the bone along the path of movement, e.g. biceps brachii and brachialis at the elbow.","Shunt muscle: origin close to the joint and insertion far from it; much of its force is directed along the bone towards the joint (compressive), stabilising the joint against centrifugal force in fast movements, e.g. brachioradialis.","Most muscles act as both depending on joint angle and speed."]},
    {h:"Tonic and phasic muscles", p:["Tonic (postural) muscles: rich in type I fibres, fatigue-resistant, cross one or two joints, maintain posture; tend to become tight and overactive (Janda), e.g. upper trapezius, levator scapulae, pectoralis major, iliopsoas, rectus femoris, hamstrings, calf, erector spinae.","Phasic muscles: rich in type II fibres, produce rapid powerful movement, fatigue quickly; tend to become weak and inhibited, e.g. deep neck flexors, lower trapezius, serratus anterior, gluteus maximus and medius, vastus medialis, abdominals.","Janda's upper and lower crossed syndromes describe these imbalance patterns."]},
    {h:"Functional roles of muscles", p:["Agonist (prime mover): the main muscle producing a movement, e.g. biceps and brachialis for elbow flexion. Assistant movers help less strongly.","Antagonist: produces the opposite movement and must relax (reciprocal inhibition) or control the motion eccentrically, e.g. triceps during elbow flexion.","Co-contraction of agonist and antagonist stabilises a joint (knee in single-leg stance)."]},
    {h:"Synergists", p:["Stabiliser (fixator): holds the proximal segment steady so the agonist can act, e.g. rotator cuff and scapular muscles during elbow work, abdominals during straight leg raise.","Neutraliser: cancels an unwanted action of the agonist, e.g. pronator teres neutralises supination by biceps when only elbow flexion is wanted.","Helping (true) synergists: two muscles with one shared action and opposite secondary actions combine, e.g. flexor carpi radialis and flexor carpi ulnaris for pure wrist flexion."]},
    {h:"Clinical relevance", p:["Muscle imbalance: stretch tight tonic muscles and strengthen weak phasic ones, as in forward-head and upper crossed posture.","PNF uses reciprocal inhibition and agonist-antagonist reversal techniques.","Weak stabilisers (e.g. serratus anterior) reduce efficiency of prime movers and cause compensation."]},
    {h:"Conclusion", p:["Classifying muscles by attachment, fibre behaviour and role helps explain normal movement, muscle imbalance and exercise choice."]}
  ],
  tip:"Draw the elbow with the biceps (origin far, insertion near: spurt) and brachioradialis (origin near, insertion far: shunt), resolving each force into rotary and compressive components.",
  evidence:[["Exercise for neck pain targeting deep neck flexors and scapular muscles","Improves pain and function","Moderate"],["Janda's tonic-phasic classification","Clinical model; limited direct experimental validation","Low"]],
  evidenceSource:"Gross et al. 2015 Cochrane review on exercise for neck pain; Page, Frank and Lardner 2010 (Janda approach)",
  outcomes:[["Craniocervical flexion test","Deep neck flexor endurance"],["Muscle length tests","Tightness of tonic muscles"],["Manual muscle testing","Weakness of phasic muscles"]],
  recent:["Surface EMG studies continue to refine which muscles act as stabilisers or movers in specific tasks, showing roles change with task and posture."],
  mnemonic:{word:"PANS", items:[["P","Prime mover (agonist)"],["A","Antagonist"],["N","Neutraliser"],["S","Stabiliser (fixator)"]], extra:"Spurt: far origin, near insertion = speed. Shunt: near origin, far insertion = stability."},
  example:"A 26-year-old IT employee in Chennai with neck pain has a forward head and rounded shoulders. Assessment shows tight upper trapezius and pectorals (tonic) and weak deep neck flexors and lower trapezius (phasic), so the programme combines stretching and targeted strengthening.",
  flags:["Neck pain with arm weakness or numbness needs neurological examination","Sudden loss of a prime mover suggests tendon rupture or nerve injury","Do not over-stretch a hypermobile joint chasing muscle imbalance"],
  viva:[["Give an example of a shunt muscle.","Brachioradialis at the elbow."],["What does a neutraliser do?","Cancels an unwanted action of the prime mover."],["Name two tonic muscles that tend to tighten.","Upper trapezius and iliopsoas (also pectoralis major, hamstrings)."]],
  refs:[{b:"brunnstrom",ch:"Muscle activity: functional roles of muscles"},{b:"levangie",ch:"Muscle structure and function: classification of muscles"},{c:"Page P, Frank CC, Lardner R. Assessment and Treatment of Muscle Imbalance: The Janda Approach. Human Kinetics; 2010."}],
  keywords:"spurt shunt MacConaill tonic phasic Janda agonist antagonist synergist fixator neutraliser",
  mcq:[["A muscle whose origin is near the joint and insertion far away is called:",["Spurt muscle","Shunt muscle","Neutraliser","Antagonist"],1,"Its force is mainly along the bone, stabilising the joint."],["Pronator teres preventing supination by biceps during elbow flexion acts as a:",["Prime mover","Antagonist","Neutraliser","Fixator"],2,"It cancels an unwanted secondary action."]]
},
{
  id:"bm-muscle-function-factors", title:"Factors affecting muscle function and strength", subject:"Kinesiology", region:"Muscle", stages:"steps",
  aliases:["factors affecting muscle strength","muscle architecture","pennate muscle","physiological cross sectional area","motor unit recruitment","fatigue","angle of pull"],
  simple:"How strong and fast a muscle is depends on its size, the way its fibres are arranged, its fibre types, its length and speed, its angle of pull and how the nervous system drives it. Age, fatigue, temperature and training also matter.",
  flow:["Structural: cross-section, fibre architecture, fibre type","Mechanical: length, velocity, moment arm, angle of pull","Neural: recruitment, rate coding, synchronisation","Physiological: fatigue, temperature, energy supply","Personal: age, sex, training, immobilisation, motivation","Use to explain weakness and plan strengthening"],
  exam:[
    {h:"Introduction", p:["Muscle function means the force, speed, range and endurance a muscle can produce. Many structural, mechanical, neural and personal factors interact."]},
    {h:"Structural factors", p:["Physiological cross-sectional area (PCSA): force is proportional to the total cross-section of fibres; hypertrophy increases force.","Fibre architecture: parallel (fusiform, strap) muscles have long fibres for range and speed (sartorius); pennate muscles (unipennate, bipennate, multipennate) pack more fibres for force (gastrocnemius, deltoid, rectus femoris).","Fibre type: type I (slow oxidative) for endurance; type IIa and IIx (fast) for power; proportion is partly genetic and changes with training.","Muscle length and number of sarcomeres in series affect range and speed."]},
    {h:"Mechanical factors", p:["Length-tension relationship: greatest active force near resting length; passive tension at long lengths.","Force-velocity: concentric force falls with speed; eccentric force is greatest.","Moment arm and angle of pull: torque is greatest when the line of pull is perpendicular to the bone.","Number of joints crossed: active and passive insufficiency in two-joint muscles.","Type of contraction: eccentric greater than isometric greater than concentric."]},
    {h:"Neural factors", p:["Number of motor units recruited (size principle: small units first).","Rate coding: higher firing frequency increases force to tetanus.","Synchronisation and coordination; early strength gains in training are mainly neural.","Reflex inhibition (pain, effusion) and central nervous system lesions reduce function."]},
    {h:"Other factors", p:["Age: strength peaks in the 20s-30s and declines with sarcopenia in old age.","Sex: men are on average stronger in absolute terms, mostly due to greater muscle mass.","Fatigue, temperature (warm muscle contracts faster), nutrition, hormones, psychological motivation and pain.","Immobilisation causes atrophy; training causes hypertrophy and neural adaptation."]},
    {h:"Clinical relevance and conclusion", p:["Strengthening programmes are designed by adjusting load, speed, range and type of contraction (PRE: about 60-80 percent of 1RM, 8-12 repetitions, 2-3 sets for strength).","Explaining weakness requires checking each factor: neural, structural, mechanical and personal."]}
  ],
  tip:"Draw a fusiform muscle and a bipennate muscle side by side with arrows showing fibre direction, and a simple flow chart grouping factors as structural, mechanical, neural and personal.",
  evidence:[["Progressive resistance training in older adults","Improves strength and some physical function","High"],["Neuromuscular electrical stimulation added to exercise after knee surgery","May improve quadriceps strength early","Low-moderate"]],
  evidenceSource:"Liu and Latham 2009 Cochrane review on progressive resistance training in older adults; ACSM position stand 2009",
  outcomes:[["1RM or handheld dynamometry","Maximal strength"],["Grip strength","General strength and sarcopenia screening"],["30-second chair stand","Lower limb functional strength"]],
  recent:["The European Working Group on Sarcopenia in Older People (EWGSOP2, 2019) uses low muscle strength as the primary sign of sarcopenia."],
  mnemonic:{word:"SMNAP", items:[["S","Size and structure (PCSA, pennation, fibre type)"],["M","Mechanics (length, velocity, moment arm)"],["N","Neural drive"],["A","Age and sex"],["P","Physiological state (fatigue, temperature, pain)"]], extra:"Early strength gains are neural; later gains are hypertrophy."},
  example:"A 72-year-old retired clerk in Madurai has difficulty rising from the floor. His weak grip and slow chair-stand suggest sarcopenia. A twice-weekly progressive resistance programme with chair stands and step-ups is started.",
  flags:["Rapid unexplained muscle weakness may be neurological or myopathic: refer","Weakness with muscle pain and dark urine after heavy exercise: suspect rhabdomyolysis","Heavy resistance with breath-holding is risky in uncontrolled hypertension"],
  viva:[["Why does a pennate muscle produce more force?","It packs more fibres per unit area, giving a larger physiological cross-section."],["What is the size principle?","Small motor units are recruited before large ones."],["Main cause of early strength gain in training?","Neural adaptation."]],
  refs:[{b:"levangie",ch:"Muscle structure and function: factors affecting muscle function"},{b:"neumann",ch:"Muscle: the primary stabiliser and mover of the skeletal system"},{c:"Liu CJ, Latham NK. Progressive resistance strength training for improving physical function in older adults. Cochrane Database Syst Rev. 2009;(3):CD002759.", q:"Liu Latham progressive resistance strength training older adults Cochrane"}],
  keywords:"factors affecting muscle function strength PCSA pennate fibre type recruitment rate coding fatigue age",
  mcq:[["Which muscle architecture favours force rather than range?",["Strap","Fusiform","Multipennate","Parallel"],2,"Pennate designs pack more fibres and increase PCSA."],["According to the size principle, motor units are recruited:",["Large before small","Small before large","Randomly","Only large ones in posture"],1,"Small, low-threshold units are recruited first."]]
},
{
  id:"bm-vertebral-articulations", title:"Vertebral column: articulations, ligaments and intervertebral disc", subject:"Kinesiology", region:"Spine", stages:"steps",
  aliases:["intervertebral disc","nucleus pulposus","annulus fibrosus","facet joints","zygapophyseal joints","spinal ligaments","ligamentum flavum"],
  simple:"The spine is a stack of vertebrae joined in front by discs and behind by small facet joints. Ligaments tie them together, and the disc acts like a water-filled cushion that spreads load and allows small movements. Together they give both flexibility and protection to the spinal cord.",
  flow:["Typical vertebra: body in front, neural arch behind","Interbody joints: disc between bodies, a symphysis","Facet joints: synovial plane joints guiding motion","Ligaments: ALL, PLL, flavum, interspinous, supraspinous","Disc: nucleus, annulus, endplates share load","Apply to disc prolapse, posture and lifting"],
  exam:[
    {h:"Introduction", p:["The vertebral column has 33 vertebrae (7 cervical, 12 thoracic, 5 lumbar, 5 fused sacral, about 4 coccygeal). It supports the trunk, protects the spinal cord and allows movement.","A motion segment (functional spinal unit) is two adjacent vertebrae with the disc, facet joints and ligaments between them."]},
    {h:"Articulations", p:["Interbody joints: secondary cartilaginous joints (symphyses) between vertebral bodies through the intervertebral disc; bear most compressive load.","Zygapophyseal (facet) joints: synovial plane joints between superior and inferior articular processes; their orientation guides the direction of motion in each region and they share load in extension.","Special joints: atlanto-occipital (condyloid; nodding), atlanto-axial (median pivot around the dens; about half of cervical rotation), uncovertebral joints (of Luschka) C3-C7, costovertebral and costotransverse joints, sacroiliac and lumbosacral joints."]},
    {h:"Ligaments", p:["Anterior longitudinal ligament (ALL): broad, on the front of bodies and discs; limits extension.","Posterior longitudinal ligament (PLL): inside the canal on the back of bodies; narrow in the lumbar region, so discs usually herniate posterolaterally; limits flexion.","Ligamentum flavum: yellow, highly elastic, joins laminae; pre-tensioned, limits flexion and prevents buckling into the canal.","Interspinous and supraspinous ligaments (ligamentum nuchae in the neck), intertransverse ligaments, and capsular ligaments of facet joints limit flexion and lateral bending."]},
    {h:"Intervertebral disc", p:["Nucleus pulposus: central gel with high water and proteoglycan content and type II collagen; distributes pressure in all directions.","Annulus fibrosus: concentric lamellae of type I collagen, fibres oblique and alternating in direction in each layer, resisting tension, torsion and shear.","Vertebral endplates: cartilage and bone layers through which the disc is nourished by diffusion; the adult disc is largely avascular, with nerve endings only in the outer annulus (sinuvertebral nerve).","Under load the nucleus pushes outward and the annulus resists; in flexion the nucleus tends to move posteriorly, in extension anteriorly. Disc height falls during the day (creep) and recovers overnight."]},
    {h:"Disc pressure and clinical relevance", p:["In vivo studies (Nachemson; later Wilke 1999) show pressure is lowest in lying, higher in standing, and highest in forward bending with a load; relaxed sitting is not much higher than standing in newer data.","Disc degeneration: dehydration, annular fissures, loss of height and stress on facets.","Disc herniation stages: protrusion, extrusion, sequestration; posterolateral prolapse compresses the nerve root (e.g. L5 or S1).","Physiotherapy: education, posture variation, lifting with load close to the body, McKenzie assessment, core and general exercise."]},
    {h:"Conclusion", p:["The coordinated work of discs, facet joints and ligaments gives the spine strength, mobility and protection; understanding them guides management of back and neck pain."]}
  ],
  tip:"Draw a sagittal section of two lumbar vertebrae with the disc (nucleus and annulus), facet joint and labelled ALL, PLL, ligamentum flavum, interspinous and supraspinous ligaments; add a top view of the disc showing alternating annular fibres.",
  evidence:[["Exercise therapy for chronic low back pain","Small to moderate improvement in pain and function","Moderate"],["McKenzie method for low back pain","Similar results to other active treatments","Low-moderate"]],
  evidenceSource:"Hayden et al. 2021 Cochrane review on exercise for chronic low back pain; Wilke et al. 1999 (Spine)",
  outcomes:[["Oswestry Disability Index","Low back related disability"],["SLR test","Nerve root tension in disc prolapse"],["NPRS","Pain intensity"]],
  recent:["Newer disc pressure data (Wilke et al. 1999) corrected the older view that relaxed sitting greatly increases disc pressure compared with standing."],
  mnemonic:{word:"A-P-F-I-S", items:[["A","ALL: limits extension"],["P","PLL: limits flexion"],["F","Flavum: elastic, yellow"],["I","Interspinous"],["S","Supraspinous / nuchae"]], extra:"Disc = nucleus (gel) + annulus (rings) + endplates (nutrition)."},
  example:"A 34-year-old courier in Chennai feels sudden back pain radiating to the right leg after lifting a heavy box while bent and twisted. SLR is positive at 40 degrees. The physiotherapist explains posterolateral disc herniation, teaches positions that ease leg pain and starts graded activity.",
  flags:["Saddle anaesthesia, bladder or bowel dysfunction: cauda equina syndrome, urgent referral","Progressive leg weakness or foot drop","Back pain with fever, weight loss, history of cancer or major trauma"],
  viva:[["Which ligament limits spinal extension?","Anterior longitudinal ligament."],["Why do discs usually prolapse posterolaterally?","The PLL is narrow in the lumbar region, leaving the posterolateral annulus weak."],["How is the adult disc nourished?","By diffusion through the vertebral endplates."]],
  refs:[{b:"levangie",ch:"The vertebral column: general structure, ligaments and intervertebral disc"},{b:"neumann",ch:"Axial skeleton: osteology and arthrology"},{c:"Wilke HJ, Neef P, Caimi M, Hoogland T, Claes LE. New in vivo measurements of pressures in the intervertebral disc in daily life. Spine. 1999;24(8):755-762.", q:"Wilke new in vivo measurements pressures intervertebral disc daily life 1999"}],
  keywords:"vertebral column articulations facet joints intervertebral disc nucleus annulus ligaments ALL PLL flavum disc pressure",
  mcq:[["The ligament that is highly elastic and joins adjacent laminae is the:",["Anterior longitudinal ligament","Posterior longitudinal ligament","Ligamentum flavum","Supraspinous ligament"],2,"Its elastin content makes it yellow and elastic."],["Facet (zygapophyseal) joints are classified as:",["Symphyses","Synovial plane joints","Syndesmoses","Synchondroses"],1,"They are synovial gliding joints."]]
},
{
  id:"bm-spine-regions", title:"Regional structure and function of the cervical, thoracic, lumbar and sacral spine", subject:"Kinesiology", region:"Spine", stages:"steps",
  aliases:["cervical spine kinesiology","thoracic spine","lumbar spine","sacrum","sacroiliac joint","spinal curves","nutation counternutation"],
  simple:"Each part of the spine is built for a different job. The neck moves the most to position the head, the thoracic spine is held stiff by the ribs to protect the chest, the lumbar spine carries heavy loads and bends forward and back, and the sacrum passes body weight to the pelvis.",
  flow:["Curves: cervical and lumbar lordosis, thoracic and sacral kyphosis","Cervical: mobile, upper and lower segments, rotation at C1-C2","Thoracic: ribs and coronal facets limit motion, allow rotation","Lumbar: large bodies, sagittal facets favour flexion-extension","Sacral: fused, transfers load via sacroiliac joints","Relate regional design to common pain and posture problems"],
  exam:[
    {h:"Spinal curves", p:["Primary (kyphotic) curves: thoracic and sacral, present at birth.","Secondary (lordotic) curves: cervical (develops with head holding) and lumbar (develops with sitting and walking).","Curves increase resistance to axial compression and act as shock absorbers."]},
    {h:"Cervical region", p:["Upper (craniovertebral): atlas has no body or spinous process; axis has the dens. Atlanto-occipital joint gives flexion-extension (nodding); atlanto-axial joint gives about half of total neck rotation. Stabilised by transverse ligament of atlas, alar ligaments and tectorial membrane.","Lower (C2-C7): small bodies, bifid spinous processes, foramen transversarium for the vertebral artery, uncinate processes; facets inclined about 45 degrees, so lateral flexion and rotation are coupled to the same side.","Most mobile region; supports and positions the head and the special senses."]},
    {h:"Thoracic region", p:["Heart-shaped bodies with costal facets; long, downward-sloping spinous processes; facets lie in the frontal plane.","Rib cage, sternum and thin discs restrict flexion, extension and lateral flexion; rotation is relatively free especially in the upper and middle segments.","Protects heart and lungs and provides attachment for breathing muscles; T11-T12 transition to lumbar-type facets."]},
    {h:"Lumbar region", p:["Large kidney-shaped bodies and thick discs to carry body weight; short horizontal spinous processes; mamillary processes.","Facets oriented mostly in the sagittal plane (more frontal near L5-S1), so flexion-extension is large and axial rotation is very small.","L5-S1: the lumbosacral angle produces anterior shear; resisted by facets of L5 against S1 and the iliolumbar ligaments; site of spondylolisthesis and disc herniation."]},
    {h:"Sacral and coccygeal region", p:["Five fused vertebrae form the sacrum, which transmits body weight to the pelvis through the sacroiliac joints.","Sacroiliac joint: synovial in front and syndesmosis behind; very small motion: nutation (sacral base moves anterior-inferior, tightened by sacrotuberous and sacrospinous ligaments) and counternutation (opposite, tightened by long dorsal sacroiliac ligament).","Form closure (bone shape) and force closure (muscles and ligaments) stabilise the SI joint.","Coccyx: attachment of pelvic floor muscles; coccydynia after falls or childbirth."]},
    {h:"Clinical relevance and conclusion", p:["Neck: whiplash, cervical spondylosis, vertebral artery screening before manual therapy.","Thoracic: hyperkyphosis, osteoporotic wedge fractures, scoliosis.","Lumbar: disc prolapse, spondylolisthesis, lumbar canal stenosis; SI: pregnancy-related pelvic girdle pain.","Regional design explains the pattern of movement and the typical injuries of each region."]}
  ],
  tip:"Draw a lateral view of the whole column with curves labelled, and beside it three small superior views of a cervical, thoracic and lumbar vertebra showing facet orientation (45 degree, frontal, sagittal).",
  evidence:[["Exercise for chronic neck pain","Improves pain and function","Moderate"],["Exercise and education for pregnancy-related pelvic girdle pain","May reduce pain and sick leave","Low"]],
  evidenceSource:"Gross et al. 2015 Cochrane review; Liddle and Pennick 2015 Cochrane review on low back and pelvic pain in pregnancy",
  outcomes:[["Neck Disability Index","Neck-related disability"],["Inclinometer or tape (Schober's test)","Lumbar flexion range"],["Active SLR test","Load transfer through pelvis"]],
  recent:["IFOMPT international framework (2020) guides examination of the cervical region for vascular pathology before manual therapy."],
  mnemonic:{word:"Neck Turns, Chest Twists, Back Bends", items:[["Neck","Most mobile; rotation at C1-C2"],["Chest","Thoracic: rotation, rib-restricted"],["Back","Lumbar: flexion-extension, little rotation"]], extra:"Sacrum moves by nutation and counternutation."},
  example:"A 28-year-old pregnant teacher in Coimbatore has pain over both sacroiliac joints when climbing stairs. The physiotherapist explains increased ligament laxity reducing force closure, and teaches pelvic stabilisation exercises and use of a pelvic belt.",
  flags:["Dizziness, diplopia, dysarthria, drop attacks with neck movement: vascular cause, avoid manipulation","Thoracic pain in an older adult after minor trauma: rule out osteoporotic fracture","Rheumatoid or Down syndrome: possible atlanto-axial instability"],
  viva:[["Which joint gives about half of cervical rotation?","Atlanto-axial joint."],["Why is lumbar rotation limited?","Facets are oriented in the sagittal plane."],["Define nutation.","Anterior-inferior movement of the sacral base relative to the ilium."]],
  refs:[{b:"levangie",ch:"The vertebral column: regional structure and function"},{b:"neumann",ch:"Axial skeleton: osteology and arthrology"},{b:"brunnstrom",ch:"Head, neck and trunk"}],
  keywords:"cervical thoracic lumbar sacral regions spinal curves facet orientation atlanto-axial sacroiliac nutation",
  mcq:[["In the lumbar spine, facet joint orientation mainly favours:",["Rotation","Flexion and extension","Lateral flexion only","No movement"],1,"Sagittal facets allow flexion-extension but block rotation."],["The foramen transversarium is a feature of:",["Thoracic vertebrae","Lumbar vertebrae","Cervical vertebrae","Sacrum"],2,"It transmits the vertebral artery."]]
},
{
  id:"bm-spinal-muscles", title:"Muscles of the vertebral column: actions and stability", subject:"Kinesiology", region:"Spine", stages:"steps",
  aliases:["back muscles","erector spinae","multifidus","transversus abdominis","core stability","abdominal muscles","quadratus lumborum"],
  simple:"Many layers of muscles move and protect the spine. Long back muscles extend it, abdominal muscles flex and rotate it, and deep small muscles like multifidus and transversus abdominis stiffen each segment. Good spinal health needs both movers and stabilisers working together.",
  flow:["Posterior muscles: erector spinae, transversospinalis, short segmental","Anterior and lateral: abdominals, psoas, quadratus lumborum","Cervical: SCM, scalenes, deep flexors, suboccipitals, splenius","Global muscles move; local muscles stabilise segments","Panjabi: passive, active and neural subsystems","Train control, endurance and strength in back and neck pain"],
  exam:[
    {h:"Posterior (back) muscles", p:["Erector spinae (iliocostalis, longissimus, spinalis): from sacrum and iliac crest to ribs, vertebrae and skull; bilateral extension, unilateral lateral flexion; eccentric control of forward bending. Nerve supply: dorsal rami of spinal nerves.","Transversospinalis (semispinalis, multifidus, rotatores): run from transverse to spinous processes; multifidus is thickest in the lumbar region and gives segmental stiffness and extension; rotatores have a role in proprioception.","Short segmental muscles: interspinales and intertransversarii, with dense muscle spindles for position sense."]},
    {h:"Anterior and lateral muscles", p:["Rectus abdominis: trunk flexion, posterior pelvic tilt (T7-T12).","External and internal obliques: flexion, lateral flexion, rotation (external oblique to opposite side, internal oblique to same side).","Transversus abdominis: deepest; increases intra-abdominal pressure and tensions the thoracolumbar fascia, stiffening the spine; activates in anticipation of limb movement.","Psoas major (L1-L4 ventral rami): hip flexor with compressive and stabilising effect on the lumbar spine; quadratus lumborum: lateral flexion and frontal-plane stability, hip hiking."]},
    {h:"Cervical muscles", p:["Sternocleidomastoid (accessory nerve): unilateral lateral flexion to same side and rotation to opposite side; bilateral flexion of neck and forward head.","Scalenes: lateral flexion and accessory breathing; deep neck flexors (longus colli, longus capitis): segmental stability and cervical curve control.","Splenius capitis and cervicis, semispinalis capitis and suboccipital muscles: extension and fine head control."]},
    {h:"Spinal stability concept", p:["Panjabi's model: passive subsystem (vertebrae, discs, ligaments), active subsystem (muscles) and neural control subsystem working together.","Local (deep) stabilisers: multifidus, transversus abdominis, pelvic floor, diaphragm. Global movers: rectus abdominis, external oblique, erector spinae.","In people with low back pain, delayed transversus abdominis activation (Hodges and Richardson 1996) and multifidus atrophy have been reported."]},
    {h:"Physiotherapy application", p:["Motor control exercise: drawing-in and multifidus swelling in neutral spine, then progress to functional tasks.","Endurance training: McGill big three (curl-up, side bridge, bird dog), holds of about 8-10 seconds in descending pyramid sets.","Deep neck flexor training with the craniocervical flexion test (pressure biofeedback from 20 to 30 mmHg).","Combine with general exercise and graded activity; no single exercise type is clearly superior."]},
    {h:"Conclusion", p:["The spinal muscles produce movement, control posture and stabilise segments; training their coordination and endurance is central to spinal rehabilitation."]}
  ],
  tip:"Draw a cross-section at L3 showing erector spinae and multifidus behind, psoas and quadratus lumborum beside the body, and the three abdominal layers wrapping around to the thoracolumbar fascia.",
  evidence:[["Motor control exercise for chronic low back pain","Better than minimal intervention but similar to other exercise","Moderate"],["Exercise therapy for chronic low back pain","Small to moderate benefit for pain and function","Moderate"]],
  evidenceSource:"Saragiotto et al. 2016 Cochrane review on motor control exercise; Hayden et al. 2021 Cochrane review",
  outcomes:[["Biering-Sorensen test","Back extensor endurance"],["Craniocervical flexion test","Deep neck flexor control"],["Oswestry Disability Index","Back-related disability"]],
  recent:["Current guidelines favour any well-tolerated exercise for chronic low back pain rather than one specific core stability method."],
  mnemonic:{word:"I Love Sweets, My Real Treat", items:[["I","Iliocostalis"],["L","Longissimus"],["S","Spinalis"],["M","Multifidus"],["R","Rotatores"],["T","Transversus abdominis"]], extra:"Erector spinae lateral to medial: I Love Spine."},
  example:"A 45-year-old bank cashier in Bengaluru with recurrent low back pain shows poor control of abdominal drawing-in. She starts motor control training in crook lying and progresses to bird dog and side bridge, along with daily walking.",
  flags:["Cauda equina symptoms need emergency referral","Night pain, weight loss or history of cancer with back pain","Pain with abdominal pulsation in older smokers: consider aortic aneurysm"],
  viva:[["Name the three columns of erector spinae.","Iliocostalis, longissimus, spinalis (lateral to medial)."],["Which muscle is thickest and most important segmental stabiliser in the lumbar spine?","Multifidus."],["Name the three subsystems in Panjabi's model.","Passive, active and neural control."]],
  refs:[{b:"neumann",ch:"Axial skeleton: muscle and joint interactions"},{b:"levangie",ch:"The vertebral column: muscles"},{c:"Saragiotto BT, Maher CG, Yamato TP, et al. Motor control exercise for chronic non-specific low-back pain. Cochrane Database Syst Rev. 2016;(1):CD012004.", q:"Saragiotto motor control exercise chronic low back pain Cochrane 2016"},{c:"Hodges PW, Richardson CA. Inefficient muscular stabilization of the lumbar spine associated with low back pain. Spine. 1996;21(22):2640-2650.", q:"Hodges Richardson inefficient muscular stabilization lumbar spine 1996"}],
  keywords:"muscles of vertebral column erector spinae multifidus transversus abdominis obliques psoas quadratus lumborum core stability",
  mcq:[["Unilateral contraction of the sternocleidomastoid rotates the head to the:",["Same side","Opposite side","No rotation, only flexion","Backward only"],1,"Right SCM turns the face to the left."],["Which muscle is a local (deep) stabiliser of the lumbar spine?",["Rectus abdominis","External oblique","Transversus abdominis","Latissimus dorsi"],2,"It stiffens the spine through intra-abdominal pressure and thoracolumbar fascia."]]
},
{
  id:"bm-lumbopelvic-rhythm", title:"Lumbopelvic rhythm; effects of injury and developmental defects of the vertebral column", subject:"Kinesiology", region:"Spine", stages:"steps",
  aliases:["lumbopelvic rhythm","lumbar pelvic rhythm","spondylolisthesis","spondylolysis","spina bifida","sacralisation lumbarisation","Klippel-Feil"],
  simple:"When you bend forward to touch your toes, the lower back and the hips share the movement in a smooth sequence called lumbopelvic rhythm. Injury, tight muscles or birth defects of the spine can disturb this sharing, overloading some parts and causing pain.",
  flow:["Forward bending: lumbar flexion then anterior pelvic tilt at hips","Return: hip extension first, then lumbar extension","Tight hamstrings or stiff hips overload the lumbar spine","Injury: disc, fracture, ligament sprain alter rhythm","Defects: spondylolysis, spina bifida, transitional and fused vertebrae","Assess rhythm and treat hip and spine mobility and control"],
  exam:[
    {h:"Lumbopelvic rhythm: definition", p:["Lumbopelvic rhythm is the coordinated movement of the lumbar spine and pelvis (hip joints) during trunk flexion and extension in the sagittal plane, which increases the total range of forward bending.","Forward bending: early phase mainly lumbar flexion, later phase mainly anterior tilt of the pelvis on the femurs (hip flexion), with overlap of both; eccentric control by erector spinae, gluteus maximus and hamstrings.","Return to upright: mainly hip extension (posterior pelvic tilt) early, followed by lumbar extension, which keeps the extensor demand on the back lower while the trunk is far forward.","Flexion-relaxation phenomenon: erector spinae become electrically silent near full flexion, as load passes to passive tissues."]},
    {h:"Altered lumbopelvic rhythm", p:["Tight hamstrings or hip stiffness reduce pelvic rotation, so the lumbar spine flexes more, increasing disc and ligament stress.","Stiff lumbar spine (ankylosing spondylitis) forces greater hip motion.","People with low back pain often show reduced and slower movement and loss of flexion-relaxation.","Lifting with knees bent and load close keeps the spine nearer neutral."]},
    {h:"Effects of injury", p:["Disc herniation: protective flexion or lateral shift, limited SLR, nerve root signs.","Vertebral fracture: wedge compression (osteoporosis), burst fracture; three-column concept of Denis guides stability.","Ligament and muscle sprain/strain; facet joint injury; whiplash in the neck.","Spinal cord injury causes paralysis below the level with loss of trunk control."]},
    {h:"Developmental defects", p:["Spondylolysis: defect in the pars interarticularis (often L5), common in young athletes with repeated extension (bowlers, gymnasts); Scotty dog collar sign on oblique X-ray.","Spondylolisthesis: forward slip of a vertebra; Wiltse types dysplastic, isthmic, degenerative, traumatic, pathological; Meyerding grades I-IV (25 percent steps) and V (spondyloptosis).","Spina bifida (occulta, meningocele, myelomeningocele), hemivertebra causing congenital scoliosis, Klippel-Feil syndrome (fused cervical vertebrae, short neck, low hairline).","Transitional vertebrae: sacralisation of L5 or lumbarisation of S1, altering lumbosacral mechanics."]},
    {h:"Physiotherapy assessment and management", p:["Observe forward bending: proportion of lumbar and hip movement, Schober's test, hamstring length (SLR), hip range.","Spondylolysis and low-grade spondylolisthesis: activity modification, avoid repeated hyperextension, flexion-biased and core stabilisation exercise, hamstring stretching.","Restore hip mobility to share load; teach hip hinge for lifting.","Defects with neurological involvement need multidisciplinary care and orthoses as needed."]},
    {h:"Conclusion", p:["Normal lumbopelvic rhythm spreads the load of bending between spine and hips; restoring it after injury or with structural defects protects the lumbar spine."]}
  ],
  tip:"Draw three stick figures in forward bending: upright, mid-bend with lumbar curve flattening, and full bend with pelvis tilted forward on femurs; add a lateral X-ray sketch of L5 slipping forward on S1 with Meyerding quarters marked.",
  evidence:[["Exercise for chronic low back pain","Small to moderate improvement","Moderate"],["Conservative care for low-grade spondylolysis in young athletes","Most return to sport with rest and rehabilitation","Low"]],
  evidenceSource:"Hayden et al. 2021 Cochrane review; Levangie and Norkin 2019",
  outcomes:[["Modified Schober's test","Lumbar flexion contribution"],["SLR or 90-90 test","Hamstring length affecting pelvic rotation"],["Oswestry Disability Index","Disability from back pain"]],
  recent:["Motion capture and wearable sensor studies continue to describe lumbopelvic rhythm in people with and without back pain, showing wide normal variation."],
  mnemonic:{word:"Down Back-Hip, Up Hip-Back", items:[["Down","Bending: lumbar first, then hips"],["Up","Returning: hips first, then lumbar"]], extra:"Meyerding grade = slip in quarters (I under 25 percent)."},
  example:"A 15-year-old fast bowler in Chennai has low back pain worse with arching the back. Oblique X-ray shows an L5 pars defect. He rests from bowling, does core stabilisation and hamstring stretching, and returns gradually to bowling with technique correction.",
  flags:["Progressive slip or neurological signs in spondylolisthesis: surgical referral","Back pain in a child or adolescent always needs careful evaluation","Saddle anaesthesia or sphincter changes: cauda equina emergency"],
  viva:[["Describe the sequence of return from forward bending.","Hips extend (pelvis tilts back) first, then the lumbar spine extends."],["What is spondylolysis?","A defect of the pars interarticularis, often at L5."],["What is sacralisation?","Fusion or partial fusion of L5 to the sacrum."]],
  refs:[{b:"levangie",ch:"The vertebral column: lumbopelvic rhythm, injury and developmental deficits"},{b:"neumann",ch:"Axial skeleton: muscle and joint interactions"},{c:"Hayden JA, Ellis J, Ogilvie R, Malmivaara A, van Tulder MW. Exercise therapy for chronic low back pain. Cochrane Database Syst Rev. 2021;(9):CD009790.", q:"Hayden exercise therapy chronic low back pain Cochrane 2021"}],
  keywords:"lumbopelvic rhythm forward bending flexion relaxation spondylolysis spondylolisthesis spina bifida sacralisation lumbarisation",
  mcq:[["During return from full forward bending, the first movement is mainly:",["Lumbar extension","Hip extension (posterior pelvic tilt)","Cervical extension","Knee extension"],1,"The pelvis rotates back on the femurs before the lumbar spine extends."],["A defect in the pars interarticularis is called:",["Spondylosis","Spondylolysis","Spondylitis","Sacralisation"],1,"Spondylolysis is a pars defect; spondylolisthesis is the slip."]]
}
]);
